/**
 * @file video_qoe_attribution.cpp
 * @brief 视频 QoE 归因实现：五行真值表 + 三条拒绝归因的前置检查
 *
 * 实现上刻意保持「无状态、无分支副作用、无默认兜底」：
 *
 * - **无默认兜底**：所有正常路径都是穷举的 if/else，末尾不留 `return NONE`。
 *   留兜底会让「新增了一个象限但忘了接上」这件事静默通过编译，
 *   而正确的行为是编译告警 / 单测失败。
 *
 * - **拒绝归因先于归因**：帧缺失、窗口错位、网络不可用这三种情况都在
 *   判定四象限之前返回，且各自给不同的 reason。混在一起会让现场无法区分
 *   「摄像头没插」与「我们自己的窗口算错了」。
 *
 * - **阈值只判画面侧**：本模块不判网络侧好坏，网络侧的 degraded 由调用方
 *   用链路侧的既有阈值算好传进来。理由见头文件——避免两套阈值互相打架。
 */

#include "video_qoe_attribution.hpp"

#include <algorithm>
#include <sstream>

namespace weaknet {

namespace {

/// 把 double 格式化成稳定的小数串（证据里不用科学计数法，便于人工阅读）
std::string fmt(double v) {
    std::ostringstream os;
    os.setf(std::ios::fixed);
    os.precision(4);
    os << v;
    return os.str();
}

std::string fmtMs(uint32_t v) {
    return std::to_string(v) + "ms";
}

/// 画面侧的具体劣化项（唯一阈值判定处）
///
/// `isFrameQualityBad` 由它派生，绝不另写一份 —— 两份阈值实现迟早会漂移，
/// 届时「是否判为差」与「差的具体成因」会互相矛盾。
///
/// 放在匿名命名空间是因为它只服务于本文件的判定表；对外暴露会让调用方
/// 误以为可以绕过 attributeVideoQoe 单独取成因，而那会丢掉窗口对齐检查。
std::vector<std::string> collectFrameIssues(const FrameStats& frames,
                                            const VideoQoeThresholds& thresholds) {
    std::vector<std::string> issues;

    // 无效统计一律视为「不知道」，不产生任何结论。
    // 这里返回空表示「没有明确地差」，由调用方决定怎么呈现 unavailable。
    if (!frames.valid()) return issues;

    if (frames.frameLossRatio() >= thresholds.frame_loss_ratio_bad) {
        issues.emplace_back("FRAME_LOSS");
    }

    if (frames.p95_gap_ms >= thresholds.frame_gap_p95_bad_ms) {
        issues.emplace_back("FRAME_GAP_P95");
    }

    if (frames.frames_expected > 0) {
        const double corrupt_ratio =
            static_cast<double>(frames.frames_corrupt) /
            static_cast<double>(frames.frames_expected);
        if (corrupt_ratio >= thresholds.frame_corrupt_ratio_bad) {
            issues.emplace_back("CORRUPT_FRAMES");
        }
    }

    return issues;
}

}  // namespace

bool isFrameQualityBad(const FrameStats& frames,
                       const VideoQoeThresholds& thresholds) {
    // 注意：无效统计一律视为「不知道」，由调用方决定怎么呈现。
    // 这里返回 false 是为了让 isFrameQualityBad 只回答「是否明确地差」，
    // 而不是把「不知道」也算进「差」——否则上游会把 unavailable 报成故障。
    return !collectFrameIssues(frames, thresholds).empty();
}

VideoQoeAttributionResult attributeVideoQoe(
    const FrameStats& frames,
    const VideoNetworkObservation& network,
    const VideoQoeThresholds& thresholds) {
    VideoQoeAttributionResult result;

    // ---- 前置检查 1：帧统计缺失 ----
    //
    // 这是最重要的一条纪律：无摄像头时归因必须是 NONE，绝不能因为
    // frames_expected==0 导致丢帧率算出 0.0 就报 CONSISTENT_HEALTHY。
    // 「不知道」伪装成「一切正常」比缺数据更危险。
    if (!frames.valid()) {
        result.attribution = VideoQoeAttribution::NONE;
        result.evaluated = false;
        result.reason = "frames_unavailable";
        result.explanation =
            "帧统计不可用（无摄像头 / 未启动 / 未采样），无法做视频 QoE 归因";
        return result;
    }

    // ---- 前置检查 2：时间窗对齐 ----
    //
    // 方案 §6.2.4 纪律：帧统计与网络指标的时间窗必须对齐，否则四象限会误判。
    // 这里选择**拒绝归因**而不是尝试近似对齐：一个 200ms 的帧窗口配 5s 的
    // 网络窗口，"画面差但网络好"完全可能是窗口错位造成的假象。
    //
    // 两侧任一方未声明窗口时长都拒绝归因：把「没填」当成「一致」正是
    // 方案里点名要避免的误判来源。
    if (frames.window_ms == 0 || network.interval_ms == 0) {
        result.attribution = VideoQoeAttribution::NONE;
        result.evaluated = false;
        result.frames_bad = isFrameQualityBad(frames, thresholds);
        result.reason = "window_length_undeclared";
        result.explanation =
            "帧统计或网络侧未声明统计窗口时长（frames.window_ms=" +
            std::to_string(frames.window_ms) + ", network.interval_ms=" +
            std::to_string(network.interval_ms) +
            "），无法确认两路证据同窗，拒绝归因";
        return result;
    }
    if (frames.window_ms != network.interval_ms) {
        result.attribution = VideoQoeAttribution::NONE;
        result.evaluated = false;
        result.frames_bad = isFrameQualityBad(frames, thresholds);
        result.reason = "window_mismatch";
        result.explanation =
            "帧窗口 " + std::to_string(frames.window_ms) + "ms 与网络窗口 " +
            std::to_string(network.interval_ms) +
            "ms 不一致，四象限在错位窗口下必然误判，拒绝归因";
        return result;
    }

    // ---- 前置检查 3：网络指标不可用 ----
    if (!network.available) {
        result.attribution = VideoQoeAttribution::NONE;
        result.evaluated = false;
        result.frames_bad = isFrameQualityBad(frames, thresholds);
        result.reason = "network_unavailable";
        result.explanation =
            "网络侧指标不可用，无法做双向校验（只有画面一路证据时不做链路归因）";
        return result;
    }

    // ================= 五行真值表 =================
    const bool frames_bad = isFrameQualityBad(frames, thresholds);
    const bool network_bad = network.degraded;
    result.frames_bad = frames_bad;
    result.evaluated = true;

    // 证据：画面侧原始事实。数值原样保留，不做任何「修匀」。
    result.evidence.push_back(EvidenceItem{
        "video_frame_loss_ratio", frames.frameLossRatio(),
        "lost=" + std::to_string(frames.framesLost()) + "/" +
            std::to_string(frames.frames_expected)});
    result.evidence.push_back(
        EvidenceItem{"video_frame_gap_p95_ms", static_cast<double>(frames.p95_gap_ms),
                     "max=" + fmtMs(frames.max_gap_ms)});
    result.evidence.push_back(
        EvidenceItem{"video_seq_gap_count", static_cast<double>(frames.seq_gap_count),
                     "gap events, not lost frames"});

    // ---- 画面好 + 网络好 ----
    if (!frames_bad && !network_bad) {
        result.attribution = VideoQoeAttribution::CONSISTENT_HEALTHY;
        result.reason = "frames_good_network_good";
        result.explanation = "画面与网络侧指标一致地正常";
        return result;
    }

    // ---- 画面差 + 网络好 ----
    if (frames_bad && !network_bad) {
        result.attribution = VideoQoeAttribution::APP_LAYER_SUSPECT;
        result.reason = "frames_bad_network_good";
        result.explanation =
            "画面劣化但网络侧指标正常，问题在应用侧或采集侧"
            "（编码器 / 内存 / CPU / sensor / ISP），不是链路";
        return result;
    }

    // ---- 画面好 + 网络差（反向校验）----
    //
    // 这是本设计最锋利的一条：不给网络开脱，而是指向我们自己。
    // 画面完全正常而协议栈说网络很差，最可能的解释是观测方法本身有问题
    // （采样过密、探针冲突、观测者过载）。
    if (!frames_bad && network_bad) {
        result.attribution = VideoQoeAttribution::NETWORK_UNVERIFIED;
        result.reason = "frames_good_network_bad";
        result.explanation =
            "网络侧指标劣化但画面正常，反向校验失败：高度怀疑观测方法本身有问题"
            "（采样过密 / 探针冲突 / 观测者过载），应转查 CPU 与 thermal 归因";
        return result;
    }

    // ---- 画面差 + 网络差：按持续性分裂 ----
    //
    // 一次丢帧就说链路坏了，会让现场人员去查一条其实没问题的线。
    // 持续多窗口才升级为高置信。
    if (network.consecutive_degraded_windows >= thresholds.confirm_windows) {
        result.attribution = VideoQoeAttribution::CONFIRMED_LINK_FAULT;
        result.reason = "frames_bad_network_bad_sustained";
        result.explanation =
            "画面与网络侧指标同时劣化且已持续 " +
            std::to_string(network.consecutive_degraded_windows) + " 个窗口（阈值 " +
            std::to_string(thresholds.confirm_windows) + "），双重确认的链路故障";
        return result;
    }

    // 到这里必然是「画面差 + 网络差 + 未持续」
    result.attribution = VideoQoeAttribution::NETWORK_TRANSIENT;
    result.reason = "frames_bad_network_bad_transient";
    result.explanation =
        "画面与网络侧指标同时劣化，但仅持续 " +
        std::to_string(network.consecutive_degraded_windows) + " 个窗口（阈值 " +
        std::to_string(thresholds.confirm_windows) + "），先观察不急于定性";
    return result;
}

}  // namespace weaknet

/**
 * @file video_qoe_attribution.hpp
 * @brief 视频 QoE 归因：用帧级事实校验网络指标，并把「我们自己错了」暴露出来
 *
 * ============================================================================
 * 与 ObserverAttribution 同构
 * ============================================================================
 *
 * 两个问题的形状完全一样：**用一路证据去校验另一路证据，且绝不互相污染**。
 * 所以结构、纪律、纯函数性质都刻意保持一致（见 assurance/observer_attribution.hpp）：
 *
 *   ObserverAttribution：eBPF 观测质量  ← 校验 →  CPU 压力
 *   VideoQoeAttribution：帧级 QoE 事实  ← 校验 →  网络指标
 *
 * ============================================================================
 * 为什么它是一个纯函数，而不是被塞进 QualityAssessor
 * ============================================================================
 *
 * 若把帧统计塞进质量评估器，会让**被观测对象的画面状态污染链路健康度判定**：
 * 同一个网络窗口，在编码器卡时和正常时会得出不同结论。那会让本项目的
 * 同源纪律与证据可复现性全部失效，也让单元测试失去可判定性。
 *
 * 正确分层：
 *   第 1 层 QualityAssessor / SLE 评估 —— 只回答「链路自己怎么样」
 *   第 2 层 VideoQoeAttribution（本模块）—— 回答「用户看到的画面跟链路指标是否一致」
 *
 * 本模块**不修改**任何 OverallPolicy / SLE 的 state/coverage/reason，
 * 只在一旁追加一个独立归因结论。上层可以同时看到两句话。
 *
 * ============================================================================
 * 语义边界（不得越过，逐条有单测守护）
 * ============================================================================
 *
 * - 帧统计缺失（无摄像头 / start 失败 / 未采样）→ 返回 NONE，**绝不**
 *   返回 CONSISTENT_HEALTHY。「不知道」不得伪装成「一切正常」。
 * - 帧统计**不能**修改 OverallPolicy 的判决，只产出归因。
 * - 帧统计与网络指标的时间窗**必须**对齐。窗口时长相同时才允许归因，
 *   不一致直接返回 NONE 并说明原因——四象限在错位窗口下必然误判。
 * - 画面好 + 网络差 = 怀疑**我们自己**（NETWORK_UNVERIFIED），不是给网络开脱，
 *   而是指向我们自己观测方法的缺陷。这是本设计最锋利的地方。
 */

#pragma once

#include <cstdint>
#include <string>
#include <vector>

#include "assurance/health_state.hpp"   // EvidenceItem
#include "frame_source.hpp"

namespace weaknet {

/**
 * @brief 视频 QoE 归因象限
 *
 * 方案 §6.2.4 的表格实际有五行（标题写「四象限」，NETWORK_UNVERIFIED 是后加的
 * 反向校验行）。这里按五行实现，外加 NONE 表示「无法归因」。
 */
enum class VideoQoeAttribution {
    /// 无法归因：帧统计缺失、窗口错位、或网络指标不可用
    ///
    /// 注意它**不是**一个"差"的结论，而是"没有结论"。
    /// 上游必须把 NONE 呈现为 unavailable，而不是 healthy。
    NONE,

    /// 画面好、网络好 —— 一切正常（唯一一个可以这么说出口的组合）
    CONSISTENT_HEALTHY,

    /// 画面差、网络好 —— 查编码器 / 内存 / CPU / sensor，不是网络
    APP_LAYER_SUSPECT,

    /// 画面差、网络也差，但**尚未持续** —— 可能是瞬态，先观察
    NETWORK_TRANSIENT,

    /// 画面差、网络差且持续多窗口 —— 双重确认，高置信链路故障
    ///
    /// 与 NETWORK_TRANSIENT 的唯一区别是持续性。一次丢帧就说链路坏了，
    /// 现场人员会被派去查一条其实没问题的线。
    CONFIRMED_LINK_FAULT,

    /// 画面好、网络指标却差 —— 反向校验失败，最可能是我们的观测方法有问题
    /// （采样过密、探针冲突、观测者过载）。应转去查 CPU / thermal 归因。
    NETWORK_UNVERIFIED,
};

inline const char* videoQoeAttributionToString(VideoQoeAttribution a) {
    switch (a) {
        case VideoQoeAttribution::NONE: return "NONE";
        case VideoQoeAttribution::CONSISTENT_HEALTHY: return "CONSISTENT_HEALTHY";
        case VideoQoeAttribution::APP_LAYER_SUSPECT: return "APP_LAYER_SUSPECT";
        case VideoQoeAttribution::NETWORK_TRANSIENT: return "NETWORK_TRANSIENT";
        case VideoQoeAttribution::CONFIRMED_LINK_FAULT: return "CONFIRMED_LINK_FAULT";
        case VideoQoeAttribution::NETWORK_UNVERIFIED: return "NETWORK_UNVERIFIED";
        default: return "NONE";
    }
}

/**
 * @brief 与帧统计同窗的网络侧观测
 *
 * 刻意不带任何「网络是否健康」的最终判定——只带症状与持续性，
 * 判定留在本模块，避免调用方替我们下结论。
 */
struct VideoNetworkObservation {
    /// 网络侧指标是否可用。不可用时无法做四象限判定（返回 NONE）
    bool available{false};

    /// 本窗口网络侧是否呈现劣化症状（丢包/重传/丢包率超阈值等）
    bool degraded{false};

    /// 连续劣化窗口数（含本窗口）。用于区分「瞬态」与「持续」
    ///
    /// 为什么由调用方传入而不是本模块自己累计：纯函数不得持有跨调用状态，
    /// 否则同一个输入会因历史不同得到不同输出，单测不可判定。
    uint32_t consecutive_degraded_windows{0};

    /// 该网络窗口的时长（毫秒）。必须与帧窗口一致，否则拒绝归因
    uint32_t interval_ms{0};
};

/**
 * @brief 判定阈值
 */
struct VideoQoeThresholds {
    /// 丢帧率达到多少算「画面差」
    double frame_loss_ratio_bad{0.05};

    /// 帧间隔 P95 超过多少毫秒算「卡顿」
    uint32_t frame_gap_p95_bad_ms{100};

    /// 坏帧率达到多少算「画面差」
    double frame_corrupt_ratio_bad{0.01};

    /// 网络劣化持续多少个窗口才算「持续」（用于 CONFIRMED_LINK_FAULT）
    uint32_t confirm_windows{3};
};

/**
 * @brief 归因结果
 */
struct VideoQoeAttributionResult {
    VideoQoeAttribution attribution{VideoQoeAttribution::NONE};

    /// 是否真的做了一次归因。false 表示输入不足（缺帧统计 / 窗口错位 / 网络不可用），
    /// 此时 attribution 必为 NONE 且 reason 说明原因。
    bool evaluated{false};

    /// 画面侧是否判为差（供证据展示，不代表链路结论）
    bool frames_bad{false};

    /// 未归因的具体原因（机器可读短句）
    std::string reason;

    /// 人类可读解释（进 warnings / 证据 detail）
    std::string explanation;

    /// 机器可读问题清单（画面侧的具体劣化项，可多条并存）
    ///
    /// 为什么它与 `explanation` 并存而不是二选一：解释是给人看的自然语言，
    /// 会被改写、会被本地化；清单是给机器匹配的稳定短标签，用于告警规则、
    /// 前端筛选与后续统计。把两者混成一个字符串字段，任何措辞调整都会
    /// 静默破坏下游匹配。
    ///
    /// 语义边界：
    /// - **只描述画面侧**。网络侧结论由 `attribution` 表达，绝不混进来。
    /// - 拒绝归因（帧缺失 / 窗口错位 / 网络不可用）时**必须为空**。
    ///   没有采到帧却说"有问题"，与把"不知道"说成"健康"同样有害。
    /// - 画面正常时为空。每轮刷一条会让告警变成噪音。
    ///
    /// 当前取值：`FRAME_LOSS` / `FRAME_GAP_P95` / `CORRUPT_FRAMES`，
    /// 与 `VideoQoeThresholds` 的三条画面阈值一一对应。
    std::vector<std::string> issues;

    /// 机器可读证据条目，直接挂到 SleResult.evidence 上
    std::vector<EvidenceItem> evidence;
};

/**
 * @brief 视频 QoE 归因判定（无状态纯函数）
 *
 * 判定顺序：
 *   1. 帧统计无效 → NONE / frames_unavailable
 *   2. 窗口时长不一致 → NONE / window_mismatch（不做近似对齐）
 *   3. 网络指标不可用 → NONE / network_unavailable
 *   4. 画面好 + 网络好  → CONSISTENT_HEALTHY
 *   5. 画面差 + 网络好  → APP_LAYER_SUSPECT
 *   6. 画面好 + 网络差  → NETWORK_UNVERIFIED
 *   7. 画面差 + 网络差，持续 < confirm_windows → NETWORK_TRANSIENT
 *   8. 画面差 + 网络差，持续 >= confirm_windows → CONFIRMED_LINK_FAULT
 *
 * 第 4~8 条是穷举的，没有落到默认分支的输入。任何新增分支都必须同时
 * 更新这里的顺序说明与单测，否则会静默改变归因含义。
 */
VideoQoeAttributionResult attributeVideoQoe(
    const FrameStats& frames,
    const VideoNetworkObservation& network,
    const VideoQoeThresholds& thresholds = VideoQoeThresholds{});

/**
 * @brief 画面侧是否判为差（暴露出来便于上游做展示，不含链路结论）
 */
bool isFrameQualityBad(const FrameStats& frames,
                       const VideoQoeThresholds& thresholds = VideoQoeThresholds{});

}  // namespace weaknet

/**
 * @file test_video_qoe_attribution_gtest.cpp
 * @brief VideoQoeAttribution 五行真值表与拒绝归因边界的契约测试
 *
 * 这份测试守的是「归因的含义」，而不是「某个数恰好是多少」。
 * 每条断言对应一个会让现场人员查错方向的失效模式：
 *
 *   1. 无摄像头时返回 NONE 而不是 CONSISTENT_HEALTHY —— 缺数据伪装成健康
 *   2. 窗口不一致时拒绝归因而不是硬算 —— 错位窗口得出反向结论
 *   3. 画面好+网络差 → NETWORK_UNVERIFIED —— 指向我们自己而非给网络开脱
 *   4. 一次丢帧不升级为 CONFIRMED_LINK_FAULT —— 误报链路故障导致乱派工
 *   5. 归因结论不写进任何 OverallPolicy 相关字段 —— 帧统计不得影响链路判决
 */

#include <gtest/gtest.h>

#include <chrono>
#include <set>
#include <string>

#include "video_qoe_attribution.hpp"

using namespace weaknet;

namespace {

/// 构造一份「画面完全正常」的帧统计
FrameStats goodFrames(uint32_t window_ms = 1000) {
    FrameStats f;
    f.frames_expected = 30;
    f.frames_received = 30;
    f.seq_gap_count = 0;
    f.max_gap_ms = 33;
    f.p95_gap_ms = 33;
    f.bytes_received = 1000000;
    f.window_ms = window_ms;
    f.sampled_at = std::chrono::steady_clock::now();
    return f;
}

/// 构造一份「画面很差」的帧统计（丢一半）
FrameStats badFrames(uint32_t window_ms = 1000) {
    FrameStats f = goodFrames(window_ms);
    f.frames_received = 15;
    f.seq_gap_count = 15;
    f.p95_gap_ms = 500;
    f.max_gap_ms = 900;
    return f;
}

VideoNetworkObservation netGood(uint32_t interval_ms = 1000) {
    VideoNetworkObservation n;
    n.available = true;
    n.degraded = false;
    n.consecutive_degraded_windows = 0;
    n.interval_ms = interval_ms;
    return n;
}

VideoNetworkObservation netBad(uint32_t interval_ms = 1000, uint32_t consecutive = 1) {
    VideoNetworkObservation n;
    n.available = true;
    n.degraded = true;
    n.consecutive_degraded_windows = consecutive;
    n.interval_ms = interval_ms;
    return n;
}

}  // namespace

// ---------------------------------------------------------------------------
// 1. 缺数据不得伪装成健康
// ---------------------------------------------------------------------------

TEST(VideoQoeAttribution, MissingFramesYieldsNoneNotHealthy) {
    // 这是整份文件最重要的一条。方案 §6.2.4 纪律明确要求：
    // 帧统计缺失时归因返回 NONE，不伪装成 CONSISTENT_HEALTHY。
    //
    // 陷阱在于：默认 FrameStats 的 frameLossRatio() 是 0.0，看起来"完美"。
    // 若不先检查 valid()，一个没插摄像头的板子会报"画面与网络一致正常"。
    FrameStats missing;

    auto r = attributeVideoQoe(missing, netGood());

    EXPECT_EQ(r.attribution, VideoQoeAttribution::NONE);
    EXPECT_FALSE(r.evaluated);
    EXPECT_EQ(r.reason, "frames_unavailable");
    EXPECT_FALSE(r.explanation.empty()) << "拒绝归因必须说明原因，不能静默";
    EXPECT_TRUE(r.evidence.empty()) << "没有采到任何东西时不得伪造证据条目";
}

TEST(VideoQoeAttribution, MissingFramesIsNoneEvenWhenNetworkIsBad) {
    // 网络差 + 没画面，也不能猜成 NETWORK_TRANSIENT —— 那等于用单路证据下结论
    auto r = attributeVideoQoe(FrameStats{}, netBad(1000, 10));

    EXPECT_EQ(r.attribution, VideoQoeAttribution::NONE);
    EXPECT_EQ(r.reason, "frames_unavailable");
}

TEST(VideoQoeAttribution, NetworkUnavailableYieldsNone) {
    VideoNetworkObservation no_net;
    no_net.available = false;
    no_net.interval_ms = 1000;

    auto r = attributeVideoQoe(goodFrames(), no_net);

    EXPECT_EQ(r.attribution, VideoQoeAttribution::NONE);
    EXPECT_FALSE(r.evaluated);
    EXPECT_EQ(r.reason, "network_unavailable");
    // 画面侧判定仍然要如实给出，便于上层单独展示"画面是好的"
    EXPECT_FALSE(r.frames_bad);
}

// ---------------------------------------------------------------------------
// 2. 窗口对齐（方案点名的误判来源）
// ---------------------------------------------------------------------------

TEST(VideoQoeAttribution, WindowMismatchRefusesToAttribute) {
    auto r = attributeVideoQoe(goodFrames(200), netGood(5000));

    EXPECT_EQ(r.attribution, VideoQoeAttribution::NONE);
    EXPECT_FALSE(r.evaluated);
    EXPECT_EQ(r.reason, "window_mismatch");
    EXPECT_NE(r.explanation.find("200"), std::string::npos)
        << "解释里必须写出实际窗口，现场才能定位是哪一侧配错了";
    EXPECT_NE(r.explanation.find("5000"), std::string::npos);
}

TEST(VideoQoeAttribution, UndeclaredWindowRefusesToAttribute) {
    // 把"没填"当成"一致"是最隐蔽的错误来源
    auto r = attributeVideoQoe(goodFrames(0), netGood(1000));
    EXPECT_EQ(r.attribution, VideoQoeAttribution::NONE);
    EXPECT_EQ(r.reason, "window_length_undeclared");

    auto r2 = attributeVideoQoe(goodFrames(1000), netGood(0));
    EXPECT_EQ(r2.attribution, VideoQoeAttribution::NONE);
    EXPECT_EQ(r2.reason, "window_length_undeclared");
}

// ---------------------------------------------------------------------------
// 3. 五行真值表
// ---------------------------------------------------------------------------

TEST(VideoQoeAttribution, BothGoodIsConsistentHealthy) {
    auto r = attributeVideoQoe(goodFrames(), netGood());

    EXPECT_EQ(r.attribution, VideoQoeAttribution::CONSISTENT_HEALTHY);
    EXPECT_TRUE(r.evaluated);
    EXPECT_FALSE(r.frames_bad);
    EXPECT_EQ(r.reason, "frames_good_network_good");
}

TEST(VideoQoeAttribution, FramesBadNetworkGoodIsAppLayerSuspect) {
    auto r = attributeVideoQoe(badFrames(), netGood());

    EXPECT_EQ(r.attribution, VideoQoeAttribution::APP_LAYER_SUSPECT);
    EXPECT_TRUE(r.frames_bad);
    EXPECT_EQ(r.reason, "frames_bad_network_good");
    // 指向应用侧，必须能从解释里看出"不是链路"
    EXPECT_NE(r.explanation.find("不是链路"), std::string::npos);
}

TEST(VideoQoeAttribution, FramesGoodNetworkBadIsNetworkUnverified) {
    // 反向校验：这是本设计最锋利的一条
    auto r = attributeVideoQoe(goodFrames(), netBad());

    EXPECT_EQ(r.attribution, VideoQoeAttribution::NETWORK_UNVERIFIED);
    EXPECT_FALSE(r.frames_bad);
    EXPECT_EQ(r.reason, "frames_good_network_bad");
    // 指向我们自己，而不是说"网络确实坏了"
    EXPECT_NE(r.explanation.find("观测方法"), std::string::npos);
}

TEST(VideoQoeAttribution, BothBadShortIsTransient) {
    auto r = attributeVideoQoe(badFrames(), netBad(1000, 1));

    EXPECT_EQ(r.attribution, VideoQoeAttribution::NETWORK_TRANSIENT);
    EXPECT_EQ(r.reason, "frames_bad_network_bad_transient");
}

TEST(VideoQoeAttribution, BothBadSustainedIsConfirmedLinkFault) {
    auto r = attributeVideoQoe(badFrames(), netBad(1000, 3));

    EXPECT_EQ(r.attribution, VideoQoeAttribution::CONFIRMED_LINK_FAULT);
    EXPECT_EQ(r.reason, "frames_bad_network_bad_sustained");
}

TEST(VideoQoeAttribution, TransientAndConfirmedDifferOnlyBySustainedness) {
    // 这两行的分界线只有持续性。若实现里写成两套不同的判定，会在某天
    // 悄悄改变含义而不被任何测试发现。
    auto transient = attributeVideoQoe(badFrames(), netBad(1000, 2));
    auto confirmed = attributeVideoQoe(badFrames(), netBad(1000, 3));

    EXPECT_EQ(transient.attribution, VideoQoeAttribution::NETWORK_TRANSIENT);
    EXPECT_EQ(confirmed.attribution, VideoQoeAttribution::CONFIRMED_LINK_FAULT);
    // 两侧都判为画面差，唯一变量就是窗口数
    EXPECT_EQ(transient.frames_bad, confirmed.frames_bad);
}

TEST(VideoQoeAttribution, ConfirmThresholdIsConfigurable) {
    VideoQoeThresholds t;
    t.confirm_windows = 5;

    auto r = attributeVideoQoe(badFrames(), netBad(1000, 3), t);

    EXPECT_EQ(r.attribution, VideoQoeAttribution::NETWORK_TRANSIENT)
        << "阈值调到 5 时，持续 3 窗口不算确认";
}

// ---------------------------------------------------------------------------
// 4. 证据条目
// ---------------------------------------------------------------------------

TEST(VideoQoeAttribution, EvidenceCarriesRawFacts) {
    auto r = attributeVideoQoe(badFrames(), netGood());

    ASSERT_FALSE(r.evidence.empty()) << "归因必须留下可追溯的原始事实";

    bool has_loss = false, has_p95 = false, has_gap = false;
    for (const auto& e : r.evidence) {
        if (e.metric == "video_frame_loss_ratio") has_loss = true;
        if (e.metric == "video_frame_gap_p95_ms") has_p95 = true;
        if (e.metric == "video_seq_gap_count") has_gap = true;
    }
    EXPECT_TRUE(has_loss);
    EXPECT_TRUE(has_p95);
    EXPECT_TRUE(has_gap);
}

TEST(VideoQoeAttribution, EvidenceLossRatioMatchesFrames) {
    FrameStats f = goodFrames();
    f.frames_received = 21;   // 丢 9 帧 / 30 = 0.3

    auto r = attributeVideoQoe(f, netGood());

    for (const auto& e : r.evidence) {
        if (e.metric == "video_frame_loss_ratio") {
            EXPECT_NEAR(e.value, 0.3, 1e-9);
            EXPECT_NE(e.detail.find("9"), std::string::npos)
                << "detail 应写出 丢/总，便于人工复核";
        }
    }
}

// ---------------------------------------------------------------------------
// 5. 画面侧判定：阈值语义
// ---------------------------------------------------------------------------

TEST(VideoQoeAttribution, FrameLossThresholdBoundary) {
    VideoQoeThresholds t;
    t.frame_loss_ratio_bad = 0.10;

    FrameStats f = goodFrames();
    f.frames_received = 27;   // 丢 3/30 = 0.10，正好等于阈值

    EXPECT_TRUE(isFrameQualityBad(f, t)) << "达到阈值即算差（>= 语义）";

    f.frames_received = 28;   // 丢 2/30 ≈ 0.067，低于阈值
    EXPECT_FALSE(isFrameQualityBad(f, t));
}

TEST(VideoQoeAttribution, P95GapAloneCanMakeFramesBad) {
    // 丢帧率为 0 但帧间隔抖得厉害，用户感知依然是卡
    FrameStats f = goodFrames();
    f.p95_gap_ms = 500;

    EXPECT_TRUE(isFrameQualityBad(f, VideoQoeThresholds{}));

    auto r = attributeVideoQoe(f, netGood());
    EXPECT_EQ(r.attribution, VideoQoeAttribution::APP_LAYER_SUSPECT)
        << "无丢帧但严重抖动，应归因应用/采集侧而非判为健康";
}

TEST(VideoQoeAttribution, CorruptFramesCount) {
    VideoQoeThresholds t;
    t.frame_corrupt_ratio_bad = 0.01;

    FrameStats f = goodFrames();
    f.frames_corrupt = 1;   // 1/30 ≈ 0.033 > 0.01

    EXPECT_TRUE(isFrameQualityBad(f, t));
}

TEST(VideoQoeAttribution, InvalidFramesAreNotCalledBad) {
    // 「不知道」既不是好也不是差，必须由调用方单独呈现
    EXPECT_FALSE(isFrameQualityBad(FrameStats{}, VideoQoeThresholds{}));
}

// ---------------------------------------------------------------------------
// 6. 纯函数性质：同一输入必然同一输出
// ---------------------------------------------------------------------------

TEST(VideoQoeAttribution, IsDeterministic) {
    auto a = attributeVideoQoe(badFrames(), netBad(1000, 2));
    auto b = attributeVideoQoe(badFrames(), netBad(1000, 2));

    EXPECT_EQ(a.attribution, b.attribution);
    EXPECT_EQ(a.reason, b.reason);
    EXPECT_EQ(a.explanation, b.explanation);
    EXPECT_EQ(a.evaluated, b.evaluated);
    EXPECT_EQ(a.evidence.size(), b.evidence.size());
}

TEST(VideoQoeAttribution, DoesNotMutateInputs) {
    // 纯函数不得持有或改写输入（防止将来有人"顺手"累加计数器）
    FrameStats f = badFrames();
    VideoNetworkObservation n = netBad(1000, 2);
    const auto f0 = f;
    const auto n0 = n;

    attributeVideoQoe(f, n);

    EXPECT_EQ(f.frames_received, f0.frames_received);
    EXPECT_EQ(f.seq_gap_count, f0.seq_gap_count);
    EXPECT_EQ(f.window_ms, f0.window_ms);
    EXPECT_EQ(n.consecutive_degraded_windows, n0.consecutive_degraded_windows);
    EXPECT_EQ(n.degraded, n0.degraded);
}

// ---------------------------------------------------------------------------
// 6.5 问题清单（issues）：机器可读的成因标签
//
// 这三个字段的形态与 thermal 同构：`<x>_attribution` 是主结论，
// `<x>_issues` 是「同一轮里还发现了哪些具体问题」。
//
// 此前 cases 缺失的后果不是"少一个字段"，而是**孤儿字段**：
// NetworkExperience 有它、legacy_adapter 序列化它、w4 测试赋值它，
// 但 server.cpp 从不赋值 —— 代码算了，运维永远读到空数组。
// ---------------------------------------------------------------------------

TEST(VideoQoeAttribution, IssuesIsEmptyWhenFramesAreGood) {
    auto r = attributeVideoQoe(goodFrames(), netGood());

    EXPECT_EQ(r.attribution, VideoQoeAttribution::CONSISTENT_HEALTHY);
    EXPECT_TRUE(r.issues.empty())
        << "画面与网络都正常时不得产生问题条目——每轮刷一条会变成噪音";
}

TEST(VideoQoeAttribution, IssuesReportEachBadAspectSeparately) {
    // 丢帧 + 卡顿 + 坏帧三种劣化同时发生，三条都要如实列出。
    // 只报主结论会丢掉"画面为什么差"的具体线索。
    FrameStats f = goodFrames();
    f.frames_received = 15;   // 丢 50% > 5%
    f.p95_gap_ms = 500;       // > 100ms
    f.frames_corrupt = 3;     // 3/30 = 10% > 1%

    auto r = attributeVideoQoe(f, netGood());

    ASSERT_EQ(r.attribution, VideoQoeAttribution::APP_LAYER_SUSPECT);
    ASSERT_EQ(r.issues.size(), 3u) << "三种劣化应各报一条";

    std::set<std::string> got(r.issues.begin(), r.issues.end());
    EXPECT_TRUE(got.count("FRAME_LOSS")) << "丢帧率超阈值必须报";
    EXPECT_TRUE(got.count("FRAME_GAP_P95")) << "帧间隔 P95 超阈值必须报";
    EXPECT_TRUE(got.count("CORRUPT_FRAMES")) << "坏帧率超阈值必须报";
}

TEST(VideoQoeAttribution, IssuesOnlyReportsWhatActuallyExceeded) {
    // 只有丢帧超标，不得顺手把卡顿与坏帧也报上。
    // 误报会让现场去查一个根本不存在的问题。
    FrameStats f = goodFrames();
    f.frames_received = 15;

    auto r = attributeVideoQoe(f, netGood());

    ASSERT_EQ(r.issues.size(), 1u);
    EXPECT_EQ(r.issues[0], "FRAME_LOSS");
}

TEST(VideoQoeAttribution, IssuesIsEmptyWhenRefusingToAttribute) {
    // 拒绝归因时没有采到任何帧，"问题清单"必须是空的——
    // 把"不知道"写成"有问题"与把"不知道"写成"健康"同样有害。
    auto r = attributeVideoQoe(FrameStats{}, netGood());

    EXPECT_EQ(r.attribution, VideoQoeAttribution::NONE);
    EXPECT_TRUE(r.issues.empty()) << "没有帧统计时不得编造成因";
}

TEST(VideoQoeAttribution, IssuesDoNotDependOnNetworkSide) {
    // 网络差但画面好 → 问题在观测方法，不在帧质量。
    // 此时 issues 必须为空：没有任何帧级劣化可报。
    auto r = attributeVideoQoe(goodFrames(), netBad(1000, 5));

    EXPECT_EQ(r.attribution, VideoQoeAttribution::NETWORK_UNVERIFIED);
    EXPECT_TRUE(r.issues.empty())
        << "画面侧没问题时不报帧级 issue，网络侧结论由 attribution 表达";
}

// ---------------------------------------------------------------------------
// 7. 枚举与字符串一致（证据/D-Bus 序列化的稳定契约）
// ---------------------------------------------------------------------------

TEST(VideoQoeAttribution, AllEnumeratorsHaveStringForms) {
    const VideoQoeAttribution all[] = {
        VideoQoeAttribution::NONE,
        VideoQoeAttribution::CONSISTENT_HEALTHY,
        VideoQoeAttribution::APP_LAYER_SUSPECT,
        VideoQoeAttribution::NETWORK_TRANSIENT,
        VideoQoeAttribution::CONFIRMED_LINK_FAULT,
        VideoQoeAttribution::NETWORK_UNVERIFIED,
    };

    std::set<std::string> names;
    for (auto a : all) {
        const std::string s = videoQoeAttributionToString(a);
        EXPECT_FALSE(s.empty());
        EXPECT_EQ(s.rfind("NONE", 0) == 0 && a != VideoQoeAttribution::NONE, false)
            << "只有 NONE 本身可以返回 NONE";
        names.insert(s);
    }
    EXPECT_EQ(names.size(), 6u) << "六个枚举必须映射到六个不同字符串";
    EXPECT_EQ(videoQoeAttributionToString(VideoQoeAttribution::CONSISTENT_HEALTHY),
              "CONSISTENT_HEALTHY");
}

