180	    profile_label_->setObjectName(QStringLiteral("meta_info"));
181	    profile_label_->setAlignment(Qt::AlignRight);
182	    meta->addWidget(profile_label_);
183	
184	    timestamp_label_ = new QLabel(QStringLiteral("--"));
185	    timestamp_label_->setObjectName(QStringLiteral("meta_info"));
186	    timestamp_label_->setAlignment(Qt::AlignRight);
187	    meta->addWidget(timestamp_label_);
188	
189	    top->addLayout(meta);
190	
191	    root->addLayout(top);
192	
193	    // --- 主区：左维度列表 / 右趋势图 ---
194	    auto* splitter = new QSplitter(Qt::Horizontal);
195	
196	    // 左侧：两个分组
197	    auto* left = new QWidget;
198	    auto* left_layout = new QVBoxLayout(left);
199	
200	    auto* net_group = new QGroupBox(QStringLiteral("网络健康"));
201	    auto* net_layout = new QVBoxLayout(net_group);
202	    net_layout->addWidget(make_status_row(QStringLiteral("IP 可达"),
203	                                          &ip_reachability_label_,
204	                                          &ip_reachability_dot_));
205	    net_layout->addWidget(make_status_row(QStringLiteral("响应性"),
206	                                          &responsiveness_label_,
207	                                          &responsiveness_dot_));
208	    net_layout->addWidget(make_status_row(QStringLiteral("可靠性"),
209	                                          &reliability_label_,
210	                                          &reliability_dot_));
211	    net_layout->addWidget(make_status_row(QStringLiteral("RF 健康"),
212	                                          &rf_health_label_, &rf_health_dot_));
213	    net_layout->addStretch();
214	    left_layout->addWidget(net_group);
215	
216	    auto* svc_group = new QGroupBox(QStringLiteral("服务健康"));
217	    auto* svc_layout = new QVBoxLayout(svc_group);
218	    svc_layout->addWidget(make_status_row(QStringLiteral("DNS"), &dns_label_,
219	                                          &dns_dot_));
220	    svc_layout->addWidget(make_status_row(QStringLiteral("TCP 连接"),
221	                                          &tcp_connect_label_,
222	                                          &tcp_connect_dot_));
223	    svc_layout->addWidget(make_status_row(QStringLiteral("TCP RTT"),
224	                                          &tcp_rtt_label_, &tcp_rtt_dot_));
225	    svc_layout->addWidget(make_status_row(QStringLiteral("HTTP 访问"),
226	                                          &http_access_label_,
227	                                          &http_access_dot_));
228	    svc_layout->addWidget(make_status_row(QStringLiteral("Portal 检测"),
229	                                          &captive_portal_label_,
230	                                          &captive_portal_dot_));
231	    svc_layout->addWidget(make_status_row(QStringLiteral("主动 DNS"),
232	                                          &active_dns_label_, &active_dns_dot_));
233	    svc_layout->addWidget(make_status_row(QStringLiteral("主动 TCP"),
234	                                          &active_tcp_label_, &active_tcp_dot_));
235	    svc_layout->addWidget(make_status_row(QStringLiteral("主动 HTTPS"),
236	                                          &active_https_label_,
237	                                          &active_https_dot_));
238	    svc_layout->addWidget(make_status_row(QStringLiteral("主动 Portal"),
239	                                          &active_portal_label_,
240	                                          &active_portal_dot_));
241	    svc_layout->addStretch();
242	    left_layout->addWidget(svc_group);
243	
244	    splitter->addWidget(left);
245	
246	    // 右侧：趋势图
247	    chart_ = new LineChartWidget;
248	    // 标题由 setInterface() 统一设置（main.cpp 无条件调用）：
249	    // 这里不再给默认值，避免两处文案各自演化后对不上实际查询范围。
250	    splitter->addWidget(chart_);
251	
252	    splitter->setStretchFactor(0, 1);
253	    splitter->setStretchFactor(1, 2);
254	    root->addWidget(splitter, 1);
