256	    // --- 底栏 ---
257	    // 每个 QLabel 只有一个所有者：写它的地方唯一，读的人随意。
258	    // 这样任一侧刷新都不会抹掉另一侧的内容。
259	    //
260	    // 归属：
261	    //   experience_label_          ← experience（等待评估 / 首要问题）
262	    //   experience_detail_label_   ← experience（警告，无警告时隐藏）
263	    //   diagnosis_label_           ← diagnosis （故障域 + 置信度 + 动作数）
264	    //   summary_template_label_    ← diagnosis （人读摘要）
265	    //   diagnosis_extra_label_     ← diagnosis （次要问题 / 排除原因 / 证据）
266	    experience_label_ = new QLabel(QStringLiteral("体验：等待数据…"));
267	    experience_label_->setObjectName(QStringLiteral("primary_text"));
268	    experience_label_->setWordWrap(true);
269	    root->addWidget(experience_label_);
270	
271	    // 体验警告（experience 独占）：服务端主动标记的异常，红色单独一行，
272	    // 不与 experience_label_ 抢位置——两者会同时有内容
273	    experience_detail_label_ = new QLabel;
274	    experience_detail_label_->setObjectName(QStringLiteral("warn_text"));
275	    experience_detail_label_->setWordWrap(true);
276	    experience_detail_label_->hide();
277	    root->addWidget(experience_detail_label_);
278	
279	    diagnosis_label_ = new QLabel(QStringLiteral("诊断：等待数据…"));
280	    diagnosis_label_->setObjectName(QStringLiteral("primary_text"));
