282	    root->addWidget(diagnosis_label_);
283	
284	    // 诊断的人读摘要（diagnosis 独占）：服务端给的是完整句子，
285	    // 比 primary_issue 这类机器 token 更适合直接展示给用户
286	    summary_template_label_ = new QLabel;
287	    summary_template_label_->setObjectName(QStringLiteral("primary_text"));
288	    summary_template_label_->setWordWrap(true);
289	    summary_template_label_->hide();
290	    root->addWidget(summary_template_label_);
291	
292	    // 次要问题 / 已排除原因 / 证据（diagnosis 独占，默认折叠）
293	    diagnosis_extra_label_ = new QLabel;
294	    diagnosis_extra_label_->setObjectName(QStringLiteral("detail_text"));
295	    diagnosis_extra_label_->setWordWrap(true);
296	    diagnosis_extra_label_->hide();
297	    root->addWidget(diagnosis_extra_label_);
298	
299	    setCentralWidget(central);
300	
301	    status_bar_label_ = new QLabel(QStringLiteral("就绪"));
302	    statusBar()->addWidget(status_bar_label_);
303	}
