332	void MainWindow::apply_diagnosis(const DiagnosisSnapshot& snap) {
333	    if (!snap.valid) {
334	        diagnosis_label_->setText(QStringLiteral("诊断：数据无效"));
335	        summary_template_label_->hide();
336	        diagnosis_extra_label_->hide();
337	        return;
338	    }
339	
340	    // 第一行：机器可判定的结论（故障域 + 置信度）
341	    // 注意 fault_domain == "NONE" 表示服务端明确判定「无需排查」
342	    // （见 diagnosis_engine.hpp:135 的 all_metrics_healthy 分支），
343	    // 不是「不知道」，所以照样展示，但把置信度放前面更醒目。
344	    QString text = QStringLiteral("诊断：故障域 %1 · 置信度 %2")
345	                       .arg(QString::fromStdString(snap.fault_domain),
346	                            QString::fromStdString(snap.confidence));
347	
348	    if (!snap.actions.empty()) {
349	        // 动作只提示数量与最优先级别，不展示 action_id：
350	        // 看板不执行任何动作，真正执行必须走 weaknet_execute_action() 且需 root。
351	        int top_priority = snap.actions.front().priority;
352	        for (const ActionSuggestion& action : snap.actions) {
353	            top_priority = std::min(top_priority, action.priority);
354	        }
355	        text += QStringLiteral(" · 建议动作 %1 项（最高优先级 %2）")
356	                    .arg(static_cast<int>(snap.actions.size()))
357	                    .arg(top_priority);
358	    }
359	    diagnosis_label_->setText(text);
360	
361	    // 第二行：人读摘要。default_summary_template 是完整句子，
362	    // 比 primary_issue 这类机器 token 更适合直接呈现给用户。
363	    //
364	    // primary_issue 作为兜底：服务端若没给 default_summary_template，
365	    // 这里就只剩 primary_issue 可选。丢掉它会让整行隐藏，而"没有摘要"
366	    // 和"没有诊断结论"在界面上是同一个样子，信息就白解析了。
367	    if (!snap.summary_template.empty()) {
368	        summary_template_label_->setText(
369	            QString::fromStdString(snap.summary_template));
370	        summary_template_label_->show();
371	    } else if (!snap.primary_issue.empty()) {
372	        // 加前缀标明这是机器标识而非完整句子，避免被当成结论直接引用
373	        summary_template_label_->setText(
374	            QStringLiteral("首要问题 %1")
375	                .arg(QString::fromStdString(snap.primary_issue)));
376	        summary_template_label_->show();
377	    } else {
378	        summary_template_label_->hide();
379	    }
380	
381	    // 第三行：次要问题 / 已排除原因 / 证据 ID。
382	    // 默认折叠成一行灰色小字；证据 ID（形如 ev_radxa_..._s101_01）是机器标识，
383	    // 铺在界面上纯噪声，放进 tooltip 让需要排查的人能查到即可。
384	    QStringList extra;
385	    QStringList evidence_tooltip;
386	    if (!snap.secondary_issues.empty()) {
387	        QStringList items;
388	        for (const std::string& issue : snap.secondary_issues) {
389	            items.append(QString::fromStdString(issue));
390	        }
391	        extra.append(QStringLiteral("次要问题 %1 项").arg(items.size()));
392	        evidence_tooltip.append(QStringLiteral("次要问题：") +
393	                                items.join(QStringLiteral("、")));
394	    }
395	    if (!snap.excluded_causes.empty()) {
396	        QStringList items;
397	        for (const ExcludedCause& cause : snap.excluded_causes) {
398	            items.append(QStringLiteral("%1（%2）")
399	                             .arg(QString::fromStdString(cause.cause),
400	                                  QString::fromStdString(cause.reason)));
401	        }
402	        extra.append(QStringLiteral("已排除 %1 项").arg(items.size()));
403	        evidence_tooltip.append(QStringLiteral("已排除原因：") +
404	                                items.join(QStringLiteral("、")));
405	    }
406	    if (!snap.evidence_refs.empty()) {
407	        QStringList items;
408	        for (const std::string& ref : snap.evidence_refs) {
409	            items.append(QString::fromStdString(ref));
410	        }
411	        extra.append(QStringLiteral("证据 %1 条").arg(items.size()));
412	        evidence_tooltip.append(QStringLiteral("证据 ID：") +
413	                                items.join(QStringLiteral("\n")));
414	    }
415	
416	    if (extra.isEmpty()) {
417	        diagnosis_extra_label_->hide();
418	        diagnosis_extra_label_->setToolTip(QString());
419	    } else {
420	        diagnosis_extra_label_->setText(extra.join(QStringLiteral("　")));
421	        diagnosis_extra_label_->setToolTip(evidence_tooltip.join(QStringLiteral("\n")));
422	        diagnosis_extra_label_->show();
423	    }
424	}
