455	void MainWindow::apply_experience(const ExperienceSnapshot& snap) {
456	    timestamp_label_->setText(
457	        QDateTime::currentDateTime().toString(QStringLiteral("yyyy-MM-dd HH:mm:ss")));
458	
459	    if (!snap.available()) {
460	        // 服务端明确说明「还没有评估」或「快照过期」——如实展示，不显示 0 分
461	        iface_label_->setText(QString::fromStdString(snap.interface_name));
462	        score_label_->setText(QStringLiteral("--"));
463	        score_label_->setStyleSheet(QString());
464	        summary_label_->clear();
465	        profile_label_->setText(QStringLiteral("--"));
466	        experience_detail_label_->hide();
467	        // 不清空 summary_template_label_ / diagnosis_extra_label_ / diagnosis_label_：
468	        // 它们归 diagnosis 所有，experience 无权处置。反过来也一样，
469	        // 这样任一侧晚到或失败都不会抹掉另一侧已经显示的内容。
470	        experience_label_->setText(
471	            QStringLiteral("体验：等待评估（%1）")
472	                .arg(QString::fromStdString(snap.unavailable_reason)));
473	        return;
474	    }
475	
476	    iface_label_->setText(QString::fromStdString(snap.interface_name));
477	    score_label_->setText(QString::number(snap.display_score, 'f', 1));
478	
479	    // 整体分数按状态着色
480	    const QString color = state_color(QString::fromStdString(snap.overall_state));
481	    score_label_->setStyleSheet(QStringLiteral("color: %1;").arg(color));
482	
483	    // 评估档位：同一维度在不同 profile 下的判定阈值不同，必须标出来
484	    profile_label_->setText(QStringLiteral("档位 %1 / 覆盖 %2")
485	                                .arg(QString::fromStdString(snap.assessment_profile),
486	                                     QString::fromStdString(snap.overall_coverage)));
487	
488	    // 各维度状态汇总：一眼看出有几个 BAD / DEGRADED，不必逐行扫
489	    int healthy = 0;
490	    int degraded = 0;
491	    int failed = 0;
492	    int unknown = 0;
493	    snap.count_by_state(&healthy, &degraded, &failed, &unknown);
494	    summary_label_->setText(
495	        QStringLiteral("<span style=\"color:%1\">● %2</span> "
496	                       "<span style=\"color:%3\">● %4</span> "
497	                       "<span style=\"color:%5\">● %6</span> "
498	                       "<span style=\"color:%7\">● %8</span>")
499	            .arg(QString::fromLatin1(ThemeColors::kGood))
500	            .arg(healthy)
501	            .arg(QString::fromLatin1(ThemeColors::kDegraded))
502	            .arg(degraded)
503	            .arg(QString::fromLatin1(ThemeColors::kBad))
504	            .arg(failed)
505	            .arg(QString::fromLatin1(ThemeColors::kUnknown))
506	            .arg(unknown));
507	
508	    // 服务端给出的警告直接展示：这是它主动标记的异常，不该被界面吞掉
509	    if (!snap.warnings.empty()) {
510	        QStringList parts;
511	        parts.reserve(static_cast<int>(snap.warnings.size()));
512	        for (const std::string& warning : snap.warnings) {
513	            parts.append(QString::fromStdString(warning));
514	        }
515	        experience_detail_label_->setText(
516	            QStringLiteral("⚠ %1").arg(parts.join(QStringLiteral(" · "))));
517	        experience_detail_label_->show();
518	    } else {
519	        experience_detail_label_->hide();
520	    }
521	
522	    // 首要问题并入结论行：experience_label_ 此时已被本函数独占写入，
523	    // 不会再被 diagnosis 侧覆盖，所以不需要第二个标签。
524	    QString text = QStringLiteral("体验：%1")
525	                       .arg(QString::fromStdString(snap.overall_state));
526	    if (!snap.primary_issue.empty()) {
527	        text += QStringLiteral(" · 首要问题 %1")
528	                    .arg(QString::fromStdString(snap.primary_issue));
529	    }
530	    experience_label_->setText(text);
531	
532	    update_status_label(snap.ip_reachability, ip_reachability_label_,
533	                        ip_reachability_dot_);
534	    update_status_label(snap.responsiveness, responsiveness_label_,
535	                        responsiveness_dot_);
536	    update_status_label(snap.reliability, reliability_label_, reliability_dot_);
537	    update_status_label(snap.rf_health, rf_health_label_, rf_health_dot_);
538	
539	    update_status_label(snap.dns_service, dns_label_, dns_dot_);
540	    update_status_label(snap.tcp_connect, tcp_connect_label_, tcp_connect_dot_);
541	    update_status_label(snap.tcp_rtt, tcp_rtt_label_, tcp_rtt_dot_);
542	    update_status_label(snap.http_access, http_access_label_, http_access_dot_);
543	    update_status_label(snap.captive_portal, captive_portal_label_,
544	                        captive_portal_dot_);
545	    update_status_label(snap.active_dns, active_dns_label_, active_dns_dot_);
546	    update_status_label(snap.active_tcp, active_tcp_label_, active_tcp_dot_);
547	    update_status_label(snap.active_https, active_https_label_,
548	                        active_https_dot_);
549	    update_status_label(snap.active_portal, active_portal_label_,
550	                        active_portal_dot_);
551	}
552	
553	void MainWindow::update_status_label(const SleItem& item, QLabel* state_label,
554	                                     QLabel* dot_label) {
555	    if (!state_label) {
556	        return;
557	    }
558	
559	    // reason 是服务端给出的人可读 token（如 jitter_excessive、no_dns_observations），
560	    // 它解释了「为什么是这个状态」。用 tooltip 挂在标签上，不占版面但可查。
561	    const QString reason = QString::fromStdString(item.reason);
562	    const QString tip = reason.isEmpty()
563	                            ? QString()
564	                            : QStringLiteral("%1：%2")
565	                                  .arg(QString::fromStdString(item.key), reason);
566	    state_label->setToolTip(tip);
567	    if (dot_label) {
568	        dot_label->setToolTip(tip);
569	    }
570	
571	    // 圆点与文字同色：改进前圆点恒为默认灰，看得出「有个点」但看不出状态，
572	    // 状态只能靠右侧文字颜色辨认，14 行扫下来很容易漏。
573	    auto paint_dot = [dot_label](const QString& color) {
574	        if (dot_label) {
575	            dot_label->setStyleSheet(QStringLiteral("color: %1;").arg(color));
576	        }
577	    };
578	
579	    // 不适用的维度（如有线链路下的 RF 健康）显式标注，不显示 GOOD/BAD
580	    if (!item.applicable()) {
581	        const QString grey = QString::fromLatin1(ThemeColors::kUnknown);
582	        state_label->setText(QStringLiteral("不适用"));
583	        state_label->setStyleSheet(QStringLiteral("color: %1;").arg(grey));
584	        paint_dot(grey);
585	        return;
586	    }
587	
588	    if (!item.has_value()) {
589	        const QString grey = QString::fromLatin1(ThemeColors::kUnknown);
590	        state_label->setText(QStringLiteral("未知"));
591	        state_label->setStyleSheet(QStringLiteral("color: %1;").arg(grey));
592	        paint_dot(grey);
593	        return;
594	    }
595	
596	    // 部分覆盖的维度加后缀，提示结论置信度较低
597	    QString text = QString::fromStdString(item.state);
598	    if (item.coverage == "PARTIAL") {
599	        text += QStringLiteral(" (部分)");
600	    }
601	    const QString color = state_color(QString::fromStdString(item.state));
602	    state_label->setText(text);
603	    state_label->setStyleSheet(QStringLiteral("color: %1;").arg(color));
604	    paint_dot(color);
605	}
606	
607	QString MainWindow::state_color(const QString& state) {
608	    // 取值依据 server/include/assurance/health_state.hpp:15-23
609	    // 色值统一从 ThemeColors 取，不在这里重写一遍：同一个绿色曾在
610	    // state_color()、summary_label_ 的 html、折线图默认色三处各写一遍。
611	    if (state == QLatin1String("GOOD")) {
612	        return QString::fromLatin1(ThemeColors::kGood);
613	    }
614	    if (state == QLatin1String("DEGRADED")) {
615	        return QString::fromLatin1(ThemeColors::kDegraded);
616	    }
617	    if (state == QLatin1String("BAD")) {
618	        return QString::fromLatin1(ThemeColors::kBad);
619	    }
620	    return QString::fromLatin1(ThemeColors::kUnknown);
621	}
