// 渲染
// ---------------------------------------------------------------------------

void MainWindow::apply_experience(const ExperienceSnapshot& snap) {
    timestamp_label_->setText(
        QDateTime::currentDateTime().toString(QStringLiteral("yyyy-MM-dd HH:mm:ss")));

    if (!snap.available()) {
        // 服务端明确说明「还没有评估」或「快照过期」——如实展示，不显示 0 分
        iface_label_->setText(QString::fromStdString(snap.interface_name));
        score_label_->setText(QStringLiteral("--"));
        score_label_->setStyleSheet(QString());
        summary_label_->clear();
        profile_label_->setText(QStringLiteral("--"));
        experience_detail_label_->hide();
        // 不清空 summary_template_label_ / diagnosis_extra_label_ / diagnosis_label_：
        // 它们归 diagnosis 所有，experience 无权处置。反过来也一样，
        // 这样任一侧晚到或失败都不会抹掉另一侧已经显示的内容。
        experience_label_->setText(
            QStringLiteral("体验：等待评估（%1）")
                .arg(QString::fromStdString(snap.unavailable_reason)));
        return;
    }

    iface_label_->setText(QString::fromStdString(snap.interface_name));
    score_label_->setText(QString::number(snap.display_score, 'f', 1));

    // 整体分数按状态着色
    const QString color = state_color(QString::fromStdString(snap.overall_state));
    score_label_->setStyleSheet(QStringLiteral("color: %1;").arg(color));

    // 评估档位：同一维度在不同 profile 下的判定阈值不同，必须标出来
    profile_label_->setText(QStringLiteral("档位 %1 / 覆盖 %2")
                                .arg(QString::fromStdString(snap.assessment_profile),
                                     QString::fromStdString(snap.overall_coverage)));

    // 各维度状态汇总：一眼看出有几个 BAD / DEGRADED，不必逐行扫
    int healthy = 0;
    int degraded = 0;
    int failed = 0;
    int unknown = 0;
    snap.count_by_state(&healthy, &degraded, &failed, &unknown);
    summary_label_->setText(
        QStringLiteral("<span style=\"color:%1\">● %2</span> "
                       "<span style=\"color:%3\">● %4</span> "
                       "<span style=\"color:%5\">● %6</span> "
                       "<span style=\"color:%7\">● %8</span>")
            .arg(QString::fromLatin1(ThemeColors::kGood))
            .arg(healthy)
            .arg(QString::fromLatin1(ThemeColors::kDegraded))
            .arg(degraded)
            .arg(QString::fromLatin1(ThemeColors::kBad))
            .arg(failed)
            .arg(QString::fromLatin1(ThemeColors::kUnknown))
            .arg(unknown));

    // 服务端给出的警告直接展示：这是它主动标记的异常，不该被界面吞掉
    if (!snap.warnings.empty()) {
        QStringList parts;
        parts.reserve(static_cast<int>(snap.warnings.size()));
        for (const std::string& warning : snap.warnings) {
            parts.append(QString::fromStdString(warning));
        }
        experience_detail_label_->setText(
            QStringLiteral("⚠ %1").arg(parts.join(QStringLiteral(" · "))));
        experience_detail_label_->show();
    } else {
        experience_detail_label_->hide();
    }

    // 首要问题并入结论行：experience_label_ 此时已被本函数独占写入，
    // 不会再被 diagnosis 侧覆盖，所以不需要第二个标签。
    QString text = QStringLiteral("体验：%1")
                       .arg(QString::fromStdString(snap.overall_state));
    if (!snap.primary_issue.empty()) {
        text += QStringLiteral(" · 首要问题 %1")
                    .arg(QString::fromStdString(snap.primary_issue));
    }
    experience_label_->setText(text);

    update_status_label(snap.ip_reachability, ip_reachability_label_,
                        ip_reachability_dot_);
    update_status_label(snap.responsiveness, responsiveness_label_,
                        responsiveness_dot_);
    update_status_label(snap.reliability, reliability_label_, reliability_dot_);
    update_status_label(snap.rf_health, rf_health_label_, rf_health_dot_);

    update_status_label(snap.dns_service, dns_label_, dns_dot_);
    update_status_label(snap.tcp_connect, tcp_connect_label_, tcp_connect_dot_);
    update_status_label(snap.tcp_rtt, tcp_rtt_label_, tcp_rtt_dot_);
    update_status_label(snap.http_access, http_access_label_, http_access_dot_);
    update_status_label(snap.captive_portal, captive_portal_label_,
                        captive_portal_dot_);
    update_status_label(snap.active_dns, active_dns_label_, active_dns_dot_);
    update_status_label(snap.active_tcp, active_tcp_label_, active_tcp_dot_);
    update_status_label(snap.active_https, active_https_label_,
                        active_https_dot_);
    update_status_label(snap.active_portal, active_portal_label_,
                        active_portal_dot_);
}

void MainWindow::update_status_label(const SleItem& item, QLabel* state_label,
                                     QLabel* dot_label) {
    if (!state_label) {
        return;
    }

    // reason 是服务端给出的人可读 token（如 jitter_excessive、no_dns_observations），
    // 它解释了「为什么是这个状态」。用 tooltip 挂在标签上，不占版面但可查。
    const QString reason = QString::fromStdString(item.reason);
    const QString tip = reason.isEmpty()
                            ? QString()
                            : QStringLiteral("%1：%2")
                                  .arg(QString::fromStdString(item.key), reason);
    state_label->setToolTip(tip);
    if (dot_label) {
        dot_label->setToolTip(tip);
    }

    // 圆点与文字同色：改进前圆点恒为默认灰，看得出「有个点」但看不出状态，
    // 状态只能靠右侧文字颜色辨认，14 行扫下来很容易漏。
    auto paint_dot = [dot_label](const QString& color) {
        if (dot_label) {
            dot_label->setStyleSheet(QStringLiteral("color: %1;").arg(color));
        }
    };

    // 不适用的维度（如有线链路下的 RF 健康）显式标注，不显示 GOOD/BAD
    if (!item.applicable()) {
        const QString grey = QString::fromLatin1(ThemeColors::kUnknown);
        state_label->setText(QStringLiteral("不适用"));
        state_label->setStyleSheet(QStringLiteral("color: %1;").arg(grey));
        paint_dot(grey);
        return;
    }

    if (!item.has_value()) {
        const QString grey = QString::fromLatin1(ThemeColors::kUnknown);
        state_label->setText(QStringLiteral("未知"));
        state_label->setStyleSheet(QStringLiteral("color: %1;").arg(grey));
        paint_dot(grey);
        return;
    }

    // 部分覆盖的维度加后缀，提示结论置信度较低
    QString text = QString::fromStdString(item.state);
    if (item.coverage == "PARTIAL") {
        text += QStringLiteral(" (部分)");
    }
    const QString color = state_color(QString::fromStdString(item.state));
    state_label->setText(text);
    state_label->setStyleSheet(QStringLiteral("color: %1;").arg(color));
    paint_dot(color);
}

QString MainWindow::state_color(const QString& state) {
    // 取值依据 server/include/assurance/health_state.hpp:15-23
    // 色值统一从 ThemeColors 取，不在这里重写一遍：同一个绿色曾在
    // state_color()、summary_label_ 的 html、折线图默认色三处各写一遍。
    if (state == QLatin1String("GOOD")) {
        return QString::fromLatin1(ThemeColors::kGood);
    }
    if (state == QLatin1String("DEGRADED")) {
        return QString::fromLatin1(ThemeColors::kDegraded);
    }
    if (state == QLatin1String("BAD")) {
        return QString::fromLatin1(ThemeColors::kBad);
    }
    return QString::fromLatin1(ThemeColors::kUnknown);
}

} // namespace dashboard
} // namespace weaknet

/**
 * @file line_chart_widget.hpp
 * @brief QPainter 自绘折线图
 *
 * ## 为什么不用 Qt Charts
 *
 * 1. 板端**没装** `libqt5charts5`（实测 `dpkg -l | grep -i chart` 为空）
 * 2. `QChart` 在 Mesa 软件渲染下帧率差
 * 3. 自绘可以 `render()` 到 `QImage` 做像素级断言，**不需要显示器**
 *
 * 第 3 点是关键：开发板目前没接 HDMI 显示器，如果图表只能在屏幕上验证，
 * 这条路在硬件到手前就是死的。渲染到 QImage 让 UI 层也能在 x86 上单测。
 *
 * ## 绘制与控件分离
 *
 * `paint(QPainter*, QRect)` 是纯绘制函数，接收 QPainter 和矩形区域，
 * 不读 `this->width()`。`paintEvent()` 只是把 `rect()` 转给它。
 *
 * 这样测试可以对任意画布做像素断言，`tests/test_line_chart_widget.cpp`
 * 就是这么用的：
 *
 * ```cpp
 * QImage img(400, 200, QImage::Format_RGB32);
 * img.fill(Qt::white);
 * QPainter p(&img);
 * chart.paint(&p, img.rect());
 * p.end();
 * // 断言 img 里出现了曲线颜色的像素
 * ```
 *
 * **这个测试必须存在**。`paint(QPainter*, QRect)` 之所以与 `paintEvent()`
 * 分离、之所以不读 `this->width()`，唯一动机就是可被像素测试；没有测试，
 * 这个分离设计本身就是只有测试才会用的孤儿接口。
 */

#ifndef WEAKNET_QT_DASHBOARD_LINE_CHART_WIDGET_HPP
#define WEAKNET_QT_DASHBOARD_LINE_CHART_WIDGET_HPP

#include <QString>
#include <QVector>
#include <QWidget>

#include "data/dashboard_data.hpp"

class QPainter;

namespace weaknet {
namespace dashboard {

/**
 * @brief 折线图控件
 *
 * 显示 `HistorySeries` 的分数随时间变化。
 *
 * 不持有数据的所有权，`setSeries()` 拷贝一份 QVector。
 */
class LineChartWidget : public QWidget {
    Q_OBJECT

public:
    explicit LineChartWidget(QWidget* parent = nullptr);

    /**
     * @brief 设置要绘制的数据
     *
     * 传入前应保证点已按时间正序排列（`parse_history()` 已做翻转）。
     *
     * `legacy` 数据点（v1 旧评分模型）会画成灰色空心点，且**不与相邻点连线**：
     * 旧模型与新模型的分数不在同一个量纲上，连成一条线会读出不存在的趋势。
     */
    void setSeries(const HistorySeries& series);

    void setTitle(const QString& title);

    /**
     * @brief 纯绘制函数
     *
     * 不依赖控件几何，可直接对任意 QPainter 调用。
     */
    void paint(QPainter* painter, const QRect& area) const;

protected:
    void paintEvent(QPaintEvent* event) override;

private:
    QVector<double> scores_;
    QVector<QString> labels_;
    /// 与 scores_ 等长：该点是否为 v1 旧评分模型的数据
    QVector<bool> legacy_;
    QString title_;
};

} // namespace dashboard
} // namespace weaknet

#endif // WEAKNET_QT_DASHBOARD_LINE_CHART_WIDGET_HPP

/**
 * @file data_fetch_thread.hpp
 * @brief 后台取数线程
 *
 * ## 为什么必须单独一个线程
 *
 * `DataSource` 的每个方法最终都走 D-Bus 同步调用
 * （`dbus_connection_send_with_reply_and_block`）。服务端忙、D-Bus 排队、
 * 或连不上服务时，单次调用可能阻塞数秒。
 *
 * 如果在 Qt 主线程调用，`QApplication::exec()` 的消息循环会停摆，
 * 界面表现为「点了没反应 / 窗口变灰 / 标题栏出现未响应」。
 *
 * ## 模式来源
 *
 * 借鉴 monitor_system 的 `DataFetchThread`（讨论文档 4.3 已认定为值得复用的
 * 标准模式）：`QThread` 子类 + `QMutex` 保护共享状态 + 信号回主线程。
 *
 * 这里做了两处改进：
 *
 * 1. **不在 `run()` 里跑无限循环**，而是用 `QTimer` 驱动的一次性任务队列，
 *    便于测试和优雅退出
 * 2. **错误也通过信号回传**，而不是只打日志——看板需要把错误显示给用户
 */

#ifndef WEAKNET_QT_DASHBOARD_DATA_FETCH_THREAD_HPP
#define WEAKNET_QT_DASHBOARD_DATA_FETCH_THREAD_HPP

#include <QByteArray>
#include <QMutex>
#include <QString>
#include <QThread>

namespace weaknet {
namespace dashboard {

/**
 * @brief 后台取数线程
 *
 * 用法：
 *
 * ```cpp
 * auto* fetcher = new DataFetchThread(this);
 * connect(fetcher, &DataFetchThread::experienceReady,
 *         this, &MainWindow::onExperience);
 * connect(fetcher, &DataFetchThread::fetchFailed,
 *         this, &MainWindow::onFetchError);
 * fetcher->start();
 * fetcher->requestRefresh();   // 可以反复调用
 * ```
 *
 * 所有信号都在**主线程**发射（Qt 自动排队），可以直接操作 UI。
 */
class DataFetchThread : public QThread {
    Q_OBJECT

public:
    explicit DataFetchThread(QObject* parent = nullptr);
    ~DataFetchThread() override;

    /**
     * @brief 请求一次完整刷新
     *
     * 非阻塞，立即返回。实际取数在后台线程执行。
     * 若上一次刷新还没结束，本次请求被丢弃（避免堆积）。
     */
    void requestRefresh();

    /**
     * @brief 设置历史查询的网卡与条数
     *
     * 在下一次 `requestRefresh()` 生效。可在任意线程调用。
     */
    void setHistoryQuery(const QString& interface_name, int limit);

    /**
     * @brief 请求线程退出
     *
     * 会等待当前这一轮取数完成后退出，不会强杀。
     * 若服务端无响应，最长可能等一个 D-Bus 超时。
     */
    void stop();

signals:
    /// 网络体验快照就绪（原始 JSON）
    void experienceReady(const QByteArray& json);

    /// 诊断事实就绪（原始 JSON）
    void diagnosisReady(const QByteArray& json);

    /// 历史趋势就绪（原始 JSON）
    void historyReady(const QByteArray& json);

    /// 任一取数失败。stage 标识是哪一步失败。
    void fetchFailed(const QString& stage, const QString& error);

    /// 一轮刷新完成（无论成败），可用于停止"加载中"动画
    void refreshFinished();

protected:
    void run() override;

private:
    // 这些成员只在后台线程读写，或由 QMutex 保护
    QMutex mutex_;
    bool refresh_pending_ = false;
    bool quit_requested_ = false;
    QString history_interface_;
    int history_limit_ = 100;
};

} // namespace dashboard
} // namespace weaknet

#endif // WEAKNET_QT_DASHBOARD_DATA_FETCH_THREAD_HPP

/**
 * @file data_source.hpp
 * @brief 取数层：调用 libweaknet 的 C API 拿原始 JSON
 *
 * ## 为什么单独一层
 *
 * 数据层（`parse_xxx`）只做 JSON → POD 的纯转换，它不知道数据从哪来。
 * 取数层负责「去拿 JSON」这件事，是唯一直接调用 `weaknet_*` 的地方。
 * 解析由调用方（主线程槽函数）调 `parse_xxx()` 完成，本层不解析。
 *
 * 分开的好处：数据层可以在没有 D-Bus、没有服务端的机器上单测；
 * 取数层可以在板端用真实服务验证。
 *
 * ## 为什么必须后台线程
 *
 * `weaknet_get_*` 内部走 D-Bus 同步调用（`dbus_connection_send_with_reply_and_block`），
 * 在服务端忙或 D-Bus 卡住时会阻塞数秒。如果在 Qt 主线程调用，界面会冻结。
 *
 * ## 缓冲区策略
 *
 * C API 的签名是 `(buffer, buffer_size, error_buffer, error_size)`，
 * 返回值只表示调用成败，不告诉你需要多大缓冲区。看板的 JSON 可能较大
 * （schema v2 快照含 13 个维度 + evidence，历史 100 条），因此采用
 * **先试小缓冲区、遇到疑似截断就扩大重试**的策略。
 *
 * 注意：C API 没有明确的「缓冲区不足」错误码，截断时可能返回 true 但
 * JSON 不完整。因此这里用 `JsonReader::valid()` 判断完整性，不合法就翻倍重试。
 */

#ifndef WEAKNET_QT_DASHBOARD_DATA_SOURCE_HPP
#define WEAKNET_QT_DASHBOARD_DATA_SOURCE_HPP

#include <cstddef>
#include <string>

namespace weaknet {
namespace dashboard {

/**
 * @brief 一次取数操作的结果
 *
 * 把「成功/失败」和「失败原因」显式分开，避免调用方拿着空字符串猜。
 */
struct FetchResult {
    /// C API 是否返回成功
    bool ok = false;

    /// 失败原因（ok 为 true 时为空）
    std::string error;

    /// 原始 JSON（调试用；失败时可能为空或被截断）
    std::string json;
};

/**
 * @brief 取数层
 *
 * 所有方法都是**阻塞**的，必须在后台线程调用，不要放在 UI 线程。
 */
class DataSource {
public:
    DataSource();
    ~DataSource();

    // 禁止拷贝：内部持有 weaknet_init/cleanup 的配对状态
    DataSource(const DataSource&) = delete;
    DataSource& operator=(const DataSource&) = delete;

    /**
     * @brief 初始化 libweaknet 并建立 D-Bus 连接
     *
     * 幂等：已成功初始化后重复调用直接返回 true。
     *
     * **失败后可重试**：失败路径内部会调用 `weaknet_cleanup()` 把库的全局
     * 客户端置空，因此可以隔一段时间再次调用 `init()` 真正重连，而不是
     * 永远停留在同一个失败结果上。板端开机早期 D-Bus 尚未就绪时依赖这一点。
     *
     * @return true 成功；false 失败（可用 last_error() 取原因）
     */
    bool init();

    /**
     * @brief 释放 D-Bus 连接
     *
     * 析构时自动调用。
     */
    void cleanup();

    /// 最近一次 init() 失败的原因
    const std::string& last_error() const { return last_error_; }

    // -----------------------------------------------------------------------
    // 取数接口（全部阻塞）
    // -----------------------------------------------------------------------

    /**
     * @brief 取网络体验快照（schema v2）
     *
     * 对应 D-Bus `GetNetworkExperience`。
     * 服务端在无快照时也会返回合法的 UNKNOWN JSON，调用方用
     * `parse_experience()` + `available()` 判断，不在这里解析。
     */
    FetchResult fetch_experience_raw() const;

    /**
     * @brief 取诊断事实
     */
    FetchResult fetch_diagnosis_raw() const;

    /**
     * @brief 取历史趋势
     *
     * @param interface 网卡名；空字符串表示全部
     * @param limit     最多返回条数（服务端上限 10000，且 <=0 会被钳制为 1）
     */
    FetchResult fetch_history_raw(const std::string& interface, int limit) const;

private:
    /**
     * @brief 通用取数模板：调用 C API 并按需扩大缓冲区
     *
     * @param caller 形如 `[](char* b, size_t n, char* e, size_t en) { return weaknet_xxx(b, n, e, en); }`
     */
    template <typename Caller>
    FetchResult invoke(Caller caller) const;

    bool initialized_ = false;
    std::string last_error_;
};

} // namespace dashboard
} // namespace weaknet

#endif // WEAKNET_QT_DASHBOARD_DATA_SOURCE_HPP

