59	void DataFetchThread::run() {
60	    DataSource source;
61	
62	    // 初始化失败**不能直接 return**：那样线程就结束了，之后 requestRefresh()
63	    // 只是往一个死掉的线程里设标志位，定时器每 10 秒照常触发但界面永远停在
64	    // 第一条"取数失败"上。这里改成重试循环，直到成功或收到退出请求。
65	    //
66	    // 每轮重试只发一次 fetchFailed，避免每隔 2 秒刷屏；成功之后 state
67	    // 复位，下次再断连时还能重新提示。
68	    bool init_ok = source.init();
69	    bool failure_reported = false;
70	    while (!init_ok) {
71	        if (!failure_reported) {
72	            emit fetchFailed(QStringLiteral("init"),
73	                             QString::fromStdString(source.last_error()));
74	            // 也要发 refreshFinished：主线程用它清 refresh_in_flight_，
75	            // 否则手动刷新按钮会永久失效。之后线程仍在重试，成功后
76	            // 会自动取数并再发一次 refreshFinished。
77	            emit refreshFinished();
78	            failure_reported = true;
79	        }
80	
81	        // 分片休眠：stop() 之后最多 kInitRetryMs 才退出，不会卡住析构
82	        for (int slept = 0; slept < kInitRetryMs; slept += 100) {
83	            {
84	                QMutexLocker lock(&mutex_);
85	                if (quit_requested_) {
86	                    return;
87	                }
88	            }
89	            QThread::msleep(100);
90	        }
91	
92	        init_ok = source.init();
93	    }
94	
95	    while (true) {
96	        bool should_quit = false;
97	        bool should_fetch = false;
98	        QString iface;
99	        int limit = 100;
100	
101	        {
102	            QMutexLocker lock(&mutex_);
103	            should_quit = quit_requested_;
104	            should_fetch = refresh_pending_;
105	            iface = history_interface_;
106	            limit = history_limit_;
107	            // 取走这次请求，避免重复执行
108	            refresh_pending_ = false;
109	        }
110	
111	        if (should_quit) {
112	            break;
113	        }
114	
115	        if (!should_fetch) {
116	            // 没有请求时短暂休眠，避免空转烧 CPU
117	            QThread::msleep(50);
118	            continue;
119	        }
120	
121	        // --- 依次取三份数据，互不阻断 ---
122	        // 某一项失败不影响其它项，让界面尽可能多地显示信息
123	
124	        const FetchResult exp = source.fetch_experience_raw();
125	        if (exp.ok) {
126	            emit experienceReady(QByteArray::fromStdString(exp.json));
127	        } else {
128	            emit fetchFailed(QStringLiteral("experience"),
129	                             QString::fromStdString(exp.error));
130	        }
131	
132	        const FetchResult diag = source.fetch_diagnosis_raw();
133	        if (diag.ok) {
134	            emit diagnosisReady(QByteArray::fromStdString(diag.json));
135	        } else {
136	            emit fetchFailed(QStringLiteral("diagnosis"),
137	                             QString::fromStdString(diag.error));
138	        }
139	
140	        const FetchResult hist =
141	            source.fetch_history_raw(iface.toStdString(), limit);
142	        if (hist.ok) {
143	            emit historyReady(QByteArray::fromStdString(hist.json));
144	        } else {
145	            emit fetchFailed(QStringLiteral("history"),
146	                             QString::fromStdString(hist.error));
147	        }
148	
149	        emit refreshFinished();
150	
151	        // 速率限制：避免连续请求
152	        QThread::msleep(kMinRefreshIntervalMs);
153	    }
