60	 * 平台插件在 `QApplication` **构造时**就要确定，而 parser 是构造之后
61	 * 才能处理的。要在那之前决定默认平台插件，只能自己看 argv。
62	 *
63	 * 只认长选项：`--screenshot` 没有短形式，这里也不该为它发明一个。
64	 */
65	static bool has_screenshot_option(int argc, char* argv[]) {
66	    static const char kOpt[] = "--screenshot";
67	    constexpr size_t kOptLen = sizeof(kOpt) - 1;
68	    for (int i = 1; i < argc; ++i) {
69	        const char* arg = argv[i];
70	        if (!arg) {
71	            continue;
72	        }
73	        if (std::strncmp(arg, kOpt, kOptLen) == 0 &&
74	            (arg[kOptLen] == '\0' || arg[kOptLen] == '=')) {
75	            return true;
76	        }
77	    }
78	    return false;
79	}
