85	 * `QT_QPA_PLATFORM` 环境变量，未设置时由 Qt 在可用插件里自行挑选，板端
86	 * 挑到哪个不确定。这里把推荐落到实处。
87	 *
88	 * 优先级（已实测确认，见下）：
89	 *
90	 * 1. `QT_QPA_PLATFORM` 环境变量已设置 → 不动
91	 * 2. 显式 `-platform <x>` → 由 Qt 自己处理，会压过这里 qputenv 的值
92	 * 3. `--screenshot` → 用 `offscreen`。这个选项的用途就是「无显示器验证」，
93	 *    此时默认 eglfs 会在 QApplication 构造时因拿不到 DRM/EGL 直接失败，
94	 *    根本走不到截图逻辑。
95	 * 4. 其余 → `eglfs`
96	 *
97	 * 实测依据（x86 无 DRM 环境）：
98	 *   - 不设环境变量：报 "Could not initialize egl display"（默认 eglfs 生效）
99	 *   - `-platform offscreen`：platformName() == "offscreen"（命令行压过默认）
100	 *   - 环境变量 offscreen：platformName() == "offscreen"（不被覆盖）
101	 */
102	static void apply_default_platform(int argc, char* argv[]) {
103	    if (!qEnvironmentVariableIsEmpty("QT_QPA_PLATFORM")) {
104	        return;  // 调用方已显式指定（命令行 -platform 或环境变量）
105	    }
106	    qputenv("QT_QPA_PLATFORM",
107	            has_screenshot_option(argc, argv) ? QByteArrayLiteral("offscreen")
108	                                             : QByteArrayLiteral("eglfs"));
109	}
110	
111	int main(int argc, char* argv[]) {
112	    apply_default_platform(argc, argv);
113	    QApplication app(argc, argv);
114	
115	    QApplication::setApplicationName(QStringLiteral("weaknet-dashboard"));
116	    QApplication::setApplicationVersion(QStringLiteral("0.1.0"));
117	    QApplication::setOrganizationName(QStringLiteral("WeakNet"));
118	
119	    // 全局外观必须在窗口构造前就位：QSS 是「样式已设置时立刻重算」，
120	    // 晚设置会让窗口先以原生样式布局一次，再跳变成主题样式。
121	    qInfo("theme: %s", qPrintable(weaknet::dashboard::apply_theme()));
122	
123	    QCommandLineParser parser;
124	    parser.setApplicationDescription(
125	        QStringLiteral("WeakNet 本地诊断看板（实验性）"));
126	    parser.addHelpOption();
127	    parser.addVersionOption();
128	
129	    QCommandLineOption iface_option(
130	        QStringList() << QStringLiteral("i") << QStringLiteral("interface"),
131	        QStringLiteral("指定网卡；不传则查询全部网卡"),
132	        QStringLiteral("name"));
133	    parser.addOption(iface_option);
134	
135	    QCommandLineOption shot_option(
136	        QStringLiteral("screenshot"),
137	        QStringLiteral("取数完成后把窗口存为 PNG 并退出（无显示器验证用）"),
138	        QStringLiteral("path"));
139	    parser.addOption(shot_option);
140	
141	    QCommandLineOption shot_delay_option(
142	        QStringLiteral("screenshot-delay"),
143	        QStringLiteral("截图前等待的毫秒数，留给首轮取数（默认 3000）"),
144	        QStringLiteral("ms"),
145	        QStringLiteral("3000"));
146	    parser.addOption(shot_delay_option);
147	
148	    parser.process(app);
149	
150	    weaknet::dashboard::MainWindow window;
151	    // 无论是否传 -i 都调用：setInterface("") 会把标题写成「全部网卡」，
152	    // 同时把 history_limit_ 设成与 -i 时同一个值。之前只在 isSet 时调用，
153	    // 导致不传 -i 时标题停在 build_ui 的默认文案、limit 也停在类默认值，
154	    // 与「查询全部网卡」的实际行为对不上。
155	    window.setInterface(parser.isSet(iface_option)
156	                            ? parser.value(iface_option)
157	                            : QString());
158	    window.show();
159	    window.start();
160	
161	    if (parser.isSet(shot_option)) {
162	        const QString path = parser.value(shot_option);
163	        const int delay_ms = parser.value(shot_delay_option).toInt();
164	        // 等待后台线程完成首轮取数，再抓窗口。
165	        // 用 singleShot 而不是 sleep：sleep 会阻塞事件循环，信号送不回主线程，
166	        // 界面就永远是未刷新状态。
167	        QTimer::singleShot(delay_ms > 0 ? delay_ms : 0, &window, [&window, path]() {
168	            const QPixmap shot = window.grab();
169	            if (shot.isNull()) {
170	                qWarning("screenshot: grab() returned null");
171	                QCoreApplication::exit(2);
172	                return;
173	            }
174	            if (!shot.save(path, "PNG")) {
175	                qWarning("screenshot: cannot save to %s", qPrintable(path));
176	                QCoreApplication::exit(3);
177	                return;
178	            }
179	            qInfo("screenshot: %dx%d saved to %s",
180	                  shot.width(), shot.height(), qPrintable(path));
181	            QCoreApplication::quit();
182	        });
183	    }
184	
185	    return app.exec();
186	}
