1	/**
2	 * @file line_chart_widget.cpp
3	 * @brief LineChartWidget 实现
4	 */
5	
6	#include "line_chart_widget.hpp"
7	
8	#include <QFontMetrics>
9	#include <QLinearGradient>
10	#include <QPainter>
11	#include <QPaintEvent>
12	#include <QPainterPath>
13	#include <QPair>
14	#include <QPen>
