19	#include "theme.hpp"
20	
21	namespace weaknet {
22	namespace dashboard {
23	
24	namespace {
25	
26	/// 绘图区相对控件边缘的留白（为坐标轴标签留空间）
27	constexpr int kMarginLeft = 44;
28	constexpr int kMarginRight = 12;
29	constexpr int kMarginTop = 28;
30	constexpr int kMarginBottom = 24;
31	
32	/// 网格线数量
33	constexpr int kGridLines = 4;
34	
35	/// 折线下方的渐变填充顶端不透明度（0-255）
36	///
37	/// 刻意压得很低：这块填充只是给曲线一个「体量感」，不能抢走线本身的注意力，
38	/// 也不能深到被像素测试当成折线。alpha=56 时混白后是 (217,231,218)，
39	/// 与折线色 (46,125,50) 的红通道差 171，远超测试的 28 容差。
40	constexpr int kAreaFillAlpha = 56;
41	
42	QColor theme_color(const char* hex) {
43	    return QColor(QString::fromLatin1(hex));
44	}
45	
46	} // namespace
47	
48	LineChartWidget::LineChartWidget(QWidget* parent) : QWidget(parent) {
49	    // 让控件至少在布局里有合理的最小尺寸
50	    setMinimumSize(240, 140);
51	}
52	
53	void LineChartWidget::setSeries(const HistorySeries& series) {
54	    scores_.clear();
55	    labels_.clear();
56	    legacy_.clear();
57	    scores_.reserve(static_cast<int>(series.points.size()));
58	    legacy_.reserve(static_cast<int>(series.points.size()));
59	    for (const HistoryPoint& p : series.points) {
60	        scores_.push_back(p.score);
61	        labels_.push_back(QString::fromStdString(p.ts));
62	        legacy_.push_back(p.legacy);
63	    }
64	    update();
65	}
66	
67	void LineChartWidget::setTitle(const QString& title) {
68	    title_ = title;
69	    update();
70	}
71	
72	void LineChartWidget::paintEvent(QPaintEvent* event) {
73	    Q_UNUSED(event);
74	    QPainter painter(this);
75	    painter.setRenderHint(QPainter::Antialiasing, true);
76	    paint(&painter, rect());
77	}
78	
79	void LineChartWidget::paint(QPainter* painter, const QRect& area) const {
80	    if (!painter || area.width() <= 0 || area.height() <= 0) {
81	        return;
82	    }
83	
84	    painter->save();
85	
86	    // --- 标题 ---
87	    if (!title_.isEmpty()) {
88	        QFont f = painter->font();
89	        f.setBold(true);
90	        painter->setFont(f);
91	        painter->setPen(theme_color(ThemeColors::kTextPrimary));
92	        painter->drawText(QRect(area.left() + kMarginLeft, area.top() + 4,
93	                                area.width() - kMarginLeft - kMarginRight, kMarginTop - 6),
94	                          Qt::AlignLeft | Qt::AlignVCenter, title_);
95	        f.setBold(false);
96	        painter->setFont(f);
97	    }
98	
99	    // --- 绘图区 ---
100	    QRect plot(area.left() + kMarginLeft,
101	               area.top() + kMarginTop,
102	               area.width() - kMarginLeft - kMarginRight,
103	               area.height() - kMarginTop - kMarginBottom);
104	
105	    if (plot.width() <= 1 || plot.height() <= 1) {
106	        painter->restore();
107	        return;
108	    }
109	
110	    // --- Y 轴范围 ---
111	    // 按数据 min/max 自适应，上下各留 10% 边距；全等值时给最小跨度避免除零。
112	    // 注意：小范围波动会被放大到撑满全高（如 20↔55 会铺满整个绘图区）。
113	    double lo = 0.0;
114	    double hi = 100.0;
115	    if (!scores_.isEmpty()) {
116	        lo = *std::min_element(scores_.constBegin(), scores_.constEnd());
117	        hi = *std::max_element(scores_.constBegin(), scores_.constEnd());
118	        const double span = hi - lo;
119	        if (span < 1e-6) {
120	            lo -= 5.0;
121	            hi += 5.0;
122	        } else {
123	            const double pad = span * 0.1;
124	            lo -= pad;
125	            hi += pad;
126	        }
127	    }
128	
129	    // --- 网格 + Y 轴刻度 ---
130	    painter->setPen(QPen(theme_color(ThemeColors::kGrid), 1, Qt::SolidLine));
131	    QFont small = painter->font();
132	    small.setPointSizeF(std::max(7.0, small.pointSizeF() - 1.0));
133	    painter->setFont(small);
134	
135	    for (int i = 0; i <= kGridLines; ++i) {
136	        const double ratio = static_cast<double>(i) / kGridLines;
137	        const int y = plot.bottom() - static_cast<int>(ratio * plot.height());
138	
139	        painter->setPen(QPen(theme_color(ThemeColors::kGrid), 1, Qt::SolidLine));
140	        painter->drawLine(plot.left(), y, plot.right(), y);
141	
142	        const double value = lo + ratio * (hi - lo);
143	        painter->setPen(theme_color(ThemeColors::kTextMuted));
144	        painter->drawText(QRect(area.left(), y - 8, kMarginLeft - 6, 16),
145	                          Qt::AlignRight | Qt::AlignVCenter,
146	                          QString::number(value, 'f', 0));
147	    }
148	
149	    // --- 数据为空时的提示 ---
150	    if (scores_.isEmpty()) {
151	        painter->setPen(theme_color(ThemeColors::kTextMuted));
152	        painter->drawText(plot, Qt::AlignCenter, QStringLiteral("暂无历史数据"));
153	        painter->restore();
154	        return;
155	    }
156	
157	    // --- 折线 ---
158	    // 单点时画一个点，避免除零
159	    const int n = scores_.size();
160	
161	    // 折线色从主题取：改进前这里是一个可写成员 `line_color_`，
162	    // 但 `setLineColor()` 作为孤儿接口被删掉后再没有人改它，
163	    // 留着成员只是把「常量」伪装成「状态」。现在直接取语义色。
164	    const QColor line_color = theme_color(ThemeColors::kGood);
165	
166	    // 先把所有点换算成屏幕坐标，连线与画点共用同一份，避免两处公式漂移
167	    QVector<QPointF> pts;
168	    pts.reserve(n);
169	    for (int i = 0; i < n; ++i) {
170	        const double x_ratio =
171	            (n == 1) ? 0.5 : static_cast<double>(i) / static_cast<double>(n - 1);
172	        const double y_ratio = (hi - lo) < 1e-9 ? 0.5 : (scores_[i] - lo) / (hi - lo);
173	        pts.push_back(QPointF(plot.left() + x_ratio * plot.width(),
174	                              plot.bottom() - y_ratio * plot.height()));
175	    }
176	
177	    // 只连 v2 点；遇到 legacy 点就断开。
178	    // legacy 是 v1 旧评分模型的分数（`data_version < 2`），与 v2 不同量纲，
179	    // 把两者连成一条线会读出一段根本不存在的趋势。
180	    //
181	    // 同时记下每个连续段的起止下标：下面的面积填充要按段闭合，
182	    // 跨段填充会在 legacy 处画出一块凭空多出来的三角。
183	    QPainterPath path;
184	    QVector<QPair<int, int>> runs;
185	    int run_begin = -1;
186	    for (int i = 0; i < n; ++i) {
187	        if (legacy_.at(i)) {
188	            if (run_begin >= 0) {
189	                runs.push_back(qMakePair(run_begin, i - 1));
190	                run_begin = -1;
191	            }
192	            continue;
193	        }
194	        if (run_begin < 0) {
195	            run_begin = i;
196	            path.moveTo(pts[i]);
197	        } else {
198	            path.lineTo(pts[i]);
199	        }
200	    }
201	    if (run_begin >= 0) {
202	        runs.push_back(qMakePair(run_begin, n - 1));
203	    }
204	
205	    // --- 曲线下方的面积填充 ---
206	    //
207	    // 先填后画线，否则填充会盖住折线。透明度很低（见 kAreaFillAlpha），
208	    // 只给曲线一个「体量感」，让整体水平一眼可见，不抢折线本身。
209	    QLinearGradient fill_grad(0, plot.top(), 0, plot.bottom());
210	    QColor fill_top = line_color;
211	    fill_top.setAlpha(kAreaFillAlpha);
212	    QColor fill_bottom = line_color;
213	    fill_bottom.setAlpha(0);
214	    fill_grad.setColorAt(0.0, fill_top);
215	    fill_grad.setColorAt(1.0, fill_bottom);
216	
217	    painter->save();
218	    painter->setClipRect(plot);
219	    painter->setPen(Qt::NoPen);
220	    painter->setBrush(fill_grad);
221	    for (const QPair<int, int>& run : runs) {
222	        // 单点没有面积，闭合后会得到一条零宽竖线，跳过
223	        if (run.second <= run.first) {
224	            continue;
225	        }
226	        QPainterPath area;
227	        area.moveTo(pts[run.first].x(), plot.bottom());
228	        for (int i = run.first; i <= run.second; ++i) {
229	            area.lineTo(pts[i]);
230	        }
231	        area.lineTo(pts[run.second].x(), plot.bottom());
232	        area.closeSubpath();
233	        painter->drawPath(area);
234	    }
235	    painter->restore();
236	
237	    painter->setPen(QPen(line_color, 2, Qt::SolidLine, Qt::RoundCap, Qt::RoundJoin));
238	    painter->setBrush(Qt::NoBrush);
239	    painter->drawPath(path);
240	
241	    // 数据点少于 30 个时补圆点，便于看清具体采样
242	    if (n <= 30) {
243	        painter->setBrush(line_color);
244	        painter->setPen(Qt::NoPen);
245	        for (int i = 0; i < n; ++i) {
246	            if (!legacy_.at(i)) {
247	                painter->drawEllipse(pts[i], 2.5, 2.5);
248	            }
249	        }
250	    }
251	
252	    // legacy 点**始终**标记（灰色空心）：它们不在折线上，若再不给标记就等于
253	    // 从图上凭空消失，比画错更糟。空心也让「不是同一条趋势」一眼可辨。
254	    painter->setBrush(Qt::NoBrush);
255	    painter->setPen(QPen(theme_color(ThemeColors::kUnknown), 1.5));
256	    for (int i = 0; i < n; ++i) {
257	        if (legacy_.at(i)) {
258	            painter->drawEllipse(pts[i], 2.5, 2.5);
259	        }
260	    }
261	
262	    // --- X 轴首尾时间标签 ---
263	    if (!labels_.isEmpty()) {
264	        painter->setPen(theme_color(ThemeColors::kTextMuted));
265	        painter->drawText(QRect(plot.left(), plot.bottom() + 4,
266	                                plot.width() / 2, kMarginBottom - 4),
267	                          Qt::AlignLeft | Qt::AlignTop, labels_.first());
268	        if (n > 1) {
269	            painter->drawText(QRect(plot.left() + plot.width() / 2, plot.bottom() + 4,
270	                                    plot.width() / 2, kMarginBottom - 4),
271	                              Qt::AlignRight | Qt::AlignTop, labels_.last());
272	        }
273	    }
274	
275	    painter->restore();
276	}
277	
278	} // namespace dashboard
279	} // namespace weaknet
