21	 *
22	 * @param reader 已构造的 JsonReader
23	 * @param base   形如 "network_health.ip_reachability"
24	 * @param key    维度标识，写回 SleItem::key
25	 */
26	SleItem parse_sle(const JsonReader& reader, const std::string& base,
27	                  const std::string& key) {
28	    SleItem item;
29	    item.key = key;
30	    item.state = reader.getString(base + ".state", "UNKNOWN");
31	    item.coverage = reader.getString(base + ".coverage", "NONE");
32	    item.applicability = reader.getString(base + ".applicability", "NOT_APPLICABLE");
33	    item.reason = reader.getString(base + ".reason");
34	    return item;
35	}
