37	/**
38	 * @brief 判断 JSON 是否为数组（首个非空白字符是 '['）
39	 */
40	bool starts_with_array(const std::string& json) {
41	    for (char c : json) {
42	        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') continue;
43	        return c == '[';
44	    }
45	    return false;
46	}
