53	
54	void ExperienceSnapshot::count_by_state(int* healthy, int* degraded,
55	                                        int* failed, int* unknown) const {
56	    int h = 0, d = 0, f = 0, u = 0;
57	    const SleItem* items[] = {
58	        &ip_reachability, &responsiveness, &reliability, &rf_health,
59	        &dns_service, &tcp_connect, &tcp_rtt, &http_access, &captive_portal,
60	        &active_dns, &active_tcp, &active_https, &active_portal,
61	    };
62	    // 状态字符串来自 healthStateToString()：GOOD / DEGRADED / BAD / UNKNOWN
63	    for (const SleItem* item : items) {
64	        if (!item->has_value()) {
65	            ++u;
66	        } else if (item->state == "GOOD") {
67	            ++h;
68	        } else if (item->state == "DEGRADED") {
69	            ++d;
70	        } else if (item->state == "BAD") {
71	            ++f;
72	        } else {
73	            ++u;
74	        }
75	    }
76	    if (healthy) *healthy = h;
77	    if (degraded) *degraded = d;
78	    if (failed) *failed = f;
79	    if (unknown) *unknown = u;
80	}
