82	ExperienceSnapshot parse_experience(const std::string& json) {
83	    ExperienceSnapshot snap;
84	    JsonReader reader(json);
85	    if (!reader.valid()) {
86	        snap.unavailable_reason = "invalid_json";
87	        return snap;
88	    }
89	
90	    snap.schema_version = reader.getInt("schema_version", 0);
91	
92	    // schema_version 是本层唯一能判断「契约是否还是我以为的那个」的依据。
93	    // 2 是当前服务端版本；0 表示字段缺失（老样本/降级形状兼容）。
94	    // 其余版本说明服务端契约已经变了，继续按 v2 字段名取值只会静默取空，
95	    // 所以直接标成不可用，让界面显示「等待评估」而不是一堆 UNKNOWN。
96	    if (snap.schema_version != 0 && snap.schema_version != 2) {
97	        snap.unavailable_reason =
98	            "unsupported_schema_version_" + std::to_string(snap.schema_version);
99	        return snap;
100	    }
101	
102	    // 先判断是否是「无快照 / 过期」的降级形状：
103	    // {"schema_version":2,"state":"UNKNOWN","coverage":"NONE","reason":"..."}
104	    // 这种形状顶层没有 overall 对象。
105	    const bool has_overall = reader.has("overall.state");
106	    if (!has_overall) {
107	        snap.overall_state = reader.getString("state", "UNKNOWN");
108	        snap.overall_coverage = reader.getString("coverage", "NONE");
109	        snap.unavailable_reason = reader.getString("reason", "unknown");
110	        return snap;
111	    }
112	
113	    snap.interface_name = reader.getString("interface");
114	    snap.assessment_profile = reader.getString("assessment_profile");
115	    snap.overall_state = reader.getString("overall.state", "UNKNOWN");
116	    snap.overall_coverage = reader.getString("overall.coverage", "NONE");
117	    snap.display_score = reader.getDouble("overall.display_score", 0.0);
118	
119	    snap.ip_reachability =
120	        parse_sle(reader, "network_health.ip_reachability", "ip_reachability");
121	    snap.responsiveness =
122	        parse_sle(reader, "network_health.responsiveness", "responsiveness");
123	    snap.reliability =
124	        parse_sle(reader, "network_health.reliability", "reliability");
125	    snap.rf_health = parse_sle(reader, "network_health.rf_health", "rf_health");
126	
127	    snap.dns_service = parse_sle(reader, "service_health.dns", "dns");
128	    snap.tcp_connect = parse_sle(reader, "service_health.tcp_connect", "tcp_connect");
129	    snap.tcp_rtt = parse_sle(reader, "service_health.tcp_rtt", "tcp_rtt");
130	    snap.http_access = parse_sle(reader, "service_health.http_access", "http_access");
131	    snap.captive_portal =
132	        parse_sle(reader, "service_health.captive_portal", "captive_portal");
133	    snap.active_dns = parse_sle(reader, "service_health.active_dns", "active_dns");
134	    snap.active_tcp = parse_sle(reader, "service_health.active_tcp", "active_tcp");
135	    snap.active_https =
136	        parse_sle(reader, "service_health.active_https", "active_https");
137	    snap.active_portal =
138	        parse_sle(reader, "service_health.active_portal", "active_portal");
139	
140	    snap.warnings = reader.getStringArray("warnings");
141	    snap.primary_issue = reader.getString("primary_issue");
142	
143	    return snap;
144	}
