2	 * @file test_json_reader.cpp
3	 * @brief 数据层单元测试
4	 *
5	 * ## 测试样本的来源
6	 *
7	 * 所有 JSON 样本都**逐字取自服务端代码**，不是臆造的：
8	 *
9	 *   - 完整快照      ← `server/include/assurance/legacy_adapter.hpp:162-227`
10	 *   - 无快照        ← `server/src/dbus_service.cpp:916-917`
11	 *   - 快照过期      ← `server/src/dbus_service.cpp:919-921`
12	 *   - 历史数组      ← `server/src/database_manager.cpp:703-740`
13	 *   - 历史不可用    ← `server/src/dbus_service.cpp:1530`
14	 *   - 诊断事实      ← `server/include/assurance/diagnosis_engine.hpp:44-85`
15	 *
16	 * 这样做的好处：如果服务端改字段名，这些测试会失败，而不是等到
17	 * 板子接上显示器才发现界面空白。
18	 *
19	 * ## 为什么能脱离 Qt 和显示器运行
20	 *
21	 * 数据层不依赖 Qt，也不依赖 D-Bus。纯字符串进、纯结构体出。
22	 * 因此可以在 x86 上用 gtest 直接跑，不需要开发板、不需要 HDMI。
23	 */
24	
25	#include <gtest/gtest.h>
26	
27	#include <algorithm>
28	
29	#include "data/dashboard_data.hpp"
30	#include "data/json_reader.hpp"
31	
32	namespace {
33	
34	using weaknet::dashboard::DiagnosisSnapshot;
35	using weaknet::dashboard::ExperienceSnapshot;
36	using weaknet::dashboard::HistorySeries;
37	using weaknet::dashboard::JsonReader;
38	
39	// ---------------------------------------------------------------------------
40	// JsonReader 基础能力
41	// ---------------------------------------------------------------------------
42	
43	TEST(JsonReaderTest, RejectsEmptyAndGarbage) {
44	    EXPECT_FALSE(JsonReader("").valid());
45	    EXPECT_FALSE(JsonReader("   ").valid());
46	    EXPECT_FALSE(JsonReader("null").valid());
47	    EXPECT_FALSE(JsonReader("\"a string\"").valid());
48	    EXPECT_FALSE(JsonReader("<html>500</html>").valid());
49	}
50	
51	TEST(JsonReaderTest, AcceptsObjectAndArray) {
52	    EXPECT_TRUE(JsonReader("{}").valid());
53	    EXPECT_TRUE(JsonReader("[]").valid());
54	    EXPECT_TRUE(JsonReader("  {\"a\":1}  ").valid());
55	    EXPECT_TRUE(JsonReader("[1,2,3]").valid());
56	}
57	
58	TEST(JsonReaderTest, ReadsTopLevelScalars) {
59	    const JsonReader r(R"({"i":2,"d":95.5,"b":true,"s":"wlan0","n":null})");
60	    EXPECT_EQ(r.getInt("i", -1), 2);
61	    EXPECT_DOUBLE_EQ(r.getDouble("d", 0.0), 95.5);
62	    EXPECT_TRUE(r.getBool("b", false));
63	    EXPECT_EQ(r.getString("s"), "wlan0");
64	
65	    // null 视为不存在
66	    EXPECT_FALSE(r.has("n"));
67	    EXPECT_EQ(r.getString("n", "fallback"), "fallback");
68	}
69	
70	TEST(JsonReaderTest, ReadsNestedPaths) {
71	    const JsonReader r(R"({"overall":{"state":"GOOD","display_score":88.5}})");
72	    EXPECT_EQ(r.getString("overall.state"), "GOOD");
73	    EXPECT_DOUBLE_EQ(r.getDouble("overall.display_score", 0.0), 88.5);
74	    EXPECT_FALSE(r.has("overall.missing"));
75	    EXPECT_FALSE(r.has("missing.state"));
76	}
77	
78	TEST(JsonReaderTest, MissingKeyReturnsFallback) {
79	    const JsonReader r(R"({"a":1})");
80	    EXPECT_EQ(r.getString("nope", "def"), "def");
81	    EXPECT_EQ(r.getInt("nope", 42), 42);
82	    EXPECT_DOUBLE_EQ(r.getDouble("nope", 3.5), 3.5);
83	    EXPECT_TRUE(r.getBool("nope", true));
84	}
85	
86	TEST(JsonReaderTest, ReadsStringArray) {
87	    const JsonReader r(R"({"warnings":["rssi_weak","dns_slow"]})");
88	    const auto warnings = r.getStringArray("warnings");
89	    ASSERT_EQ(warnings.size(), 2u);
90	    EXPECT_EQ(warnings[0], "rssi_weak");
91	    EXPECT_EQ(warnings[1], "dns_slow");
92	}
93	
94	TEST(JsonReaderTest, EmptyArrayYieldsEmptyVector) {
95	    const JsonReader r(R"({"warnings":[]})");
96	    EXPECT_TRUE(r.getStringArray("warnings").empty());
97	}
98	
99	TEST(JsonReaderTest, ReadsObjectArray) {
100	    const JsonReader r(R"({"evidence":[{"metric":"rtt","value":25},{"metric":"loss","value":0}]})");
101	    const auto items = r.getObjectArray("evidence");
102	    ASSERT_EQ(items.size(), 2u);
