106	
107	TEST(JsonReaderTest, HandlesEscapedStrings) {
108	    const JsonReader r(R"({"s":"a\"b\\c\nd"})");
109	    EXPECT_EQ(r.getString("s"), "a\"b\\c\nd");
110	}
111	
112	TEST(JsonReaderTest, DoesNotConfuseNestedBracesInStrings) {
113	    // 字符串里的 } 和 , 不应干扰扫描
114	    const JsonReader r(R"({"a":"x},y{","b":2})");
115	    EXPECT_EQ(r.getString("a"), "x},y{");
116	    EXPECT_EQ(r.getInt("b", -1), 2);
