119	TEST(JsonReaderTest, ReadsRootArray) {
120	    const JsonReader r(R"([{"x":1},{"x":2}])");
121	    const auto elems = r.getRootObjectArray();
122	    ASSERT_EQ(elems.size(), 2u);
