136	/// 两条 RGB 是否接近（容忍抗锯齿带来的通道偏差）
137	bool close_to(int r, int g, int b, int tr, int tg, int tb, int tol = 28) {
138	    return std::abs(r - tr) <= tol && std::abs(g - tg) <= tol &&
139	           std::abs(b - tb) <= tol;
140	}
