263	        << "legacy 点必须留下灰色空心标记，不能静默消失";
264	}
265	
266	// ---------------------------------------------------------------------------
267	// 几何与坐标变换
268	// ---------------------------------------------------------------------------
269	
270	TEST(LineChartWidgetTest, SinglePointRendersWithoutDivisionByZero) {
271	    // n == 1 时 x_ratio 被特意设为 0.5，避免除零。
272	    // 这类边界不值得为它崩一次界面。
273	    LineChartWidget chart;
274	    chart.setSeries(make_series(1));
275	    const QImage img = render(chart);
276	
277	    EXPECT_GT(count_in_plot(img, /*want_line=*/true, /*want_gray=*/false), 0)
278	        << "单点也必须画出来（画成圆点，不画线）";
279	}
