281	TEST(LineChartWidgetTest, FlatSeriesDoesNotCollapseToEdge) {
282	    // 全等值序列：hi == lo，y_ratio 会退化成 0.5。
283	    // 若没有 span 兜底，取值会落到绘图区顶部或底部，看起来像"贴顶"。
284	    HistorySeries flat;
285	    for (int i = 0; i < 5; ++i) {
286	        HistoryPoint p;
