312	TEST(LineChartWidgetTest, LegacyVectorStaysInSyncWithScores) {
313	    // legacy_ 与 scores_ 必须等长：paint() 里用 legacy_.at(i) 索引，
314	    // 长度不一致会越界。连续换两次数据是这个不变量的最容易破的时刻。
315	    LineChartWidget chart;
