1	/**
2	 * @file json_reader.cpp
3	 * @brief JsonReader 实现
4	 */
5	
6	#include "json_reader.hpp"
7	
8	#include <cctype>
9	#include <cstdlib>
10	
11	namespace weaknet {
12	namespace dashboard {
13	
14	namespace {
15	
16	/**
17	 * @brief 判断字符是否为 JSON 空白
18	 *
19	 * 只认 RFC 8259 定义的四种：空格、水平制表、换行、回车。
20	 * 不用 std::isspace，因为它还认垂直制表和换页，JSON 不允许。
21	 */
22	inline bool isJsonSpace(char c) {
23	    return c == ' ' || c == '\t' || c == '\n' || c == '\r';
24	}
25	
26	} // namespace
27	
28	JsonReader::JsonReader(const std::string& json) : json_(json) {}
29	
30	// ---------------------------------------------------------------------------
31	// 基础扫描
32	// ---------------------------------------------------------------------------
33	
34	size_t JsonReader::skipWhitespace(size_t pos) const {
35	    while (pos < json_.size() && isJsonSpace(json_[pos])) {
36	        ++pos;
37	    }
38	    return pos;
39	}
40	
41	bool JsonReader::valid() const {
42	    size_t begin = skipWhitespace(0);
43	    if (begin >= json_.size()) {
44	        return false;
45	    }
46	    // 只接受对象或数组开头的 JSON
47	    if (json_[begin] != '{' && json_[begin] != '[') {
48	        return false;
49	    }
50	    // 末尾必须能闭合。不校验中间内容，那是 getXxx 的事。
51	    size_t end = json_.size();
52	    while (end > begin && isJsonSpace(json_[end - 1])) {
53	        --end;
54	    }
55	    if (end <= begin) {
56	        return false;
57	    }
58	    const char last = json_[end - 1];
59	    return last == '}' || last == ']';
60	}
61	
62	size_t JsonReader::skipString(size_t pos) const {
63	    if (pos >= json_.size() || json_[pos] != '"') {
64	        return pos;
65	    }
66	    ++pos;
67	    while (pos < json_.size()) {
68	        if (json_[pos] == '\\') {
69	            // 跳过转义字符。\uXXXX 的六字符形式也一并跳过，
70	            // 这里不需要真的解码，只要不误判引号即可。
71	            pos += 2;
72	            continue;
73	        }
74	        if (json_[pos] == '"') {
75	            return pos + 1;
76	        }
77	        ++pos;
78	    }
79	    return json_.size();
80	}
81	
82	size_t JsonReader::skipContainer(size_t pos) const {
83	    if (pos >= json_.size()) {
84	        return pos;
85	    }
86	    const char open = json_[pos];
87	    if (open != '{' && open != '[') {
88	        return pos;
89	    }
90	    const char close = (open == '{') ? '}' : ']';
91	
92	    int depth = 0;
93	    while (pos < json_.size()) {
94	        const char c = json_[pos];
95	        if (c == '"') {
96	            pos = skipString(pos);
97	            continue;
98	        }
99	        if (c == open) {
100	            ++depth;
101	        } else if (c == close) {
102	            --depth;
103	            if (depth == 0) {
104	                return pos + 1;
105	            }
106	        }
107	        ++pos;
108	    }
109	    return json_.size();
110	}
111	
112	size_t JsonReader::skipValue(size_t pos) const {
113	    pos = skipWhitespace(pos);
114	    if (pos >= json_.size()) {
115	        return pos;
116	    }
117	    const char c = json_[pos];
118	    if (c == '"') {
119	        return skipString(pos);
120	    }
121	    if (c == '{' || c == '[') {
122	        return skipContainer(pos);
123	    }
124	    // 数字 / true / false / null：一直吃到分隔符
125	    while (pos < json_.size()) {
126	        const char d = json_[pos];
127	        if (d == ',' || d == '}' || d == ']' || isJsonSpace(d)) {
128	            break;
129	        }
130	        ++pos;
131	    }
132	    return pos;
133	}
134	
135	std::string JsonReader::parseStringAt(size_t pos, size_t* end_out) const {
136	    std::string out;
137	    if (pos >= json_.size() || json_[pos] != '"') {
138	        if (end_out) *end_out = pos;
139	        return out;
140	    }
141	    ++pos;
142	    while (pos < json_.size()) {
143	        const char c = json_[pos];
144	        if (c == '\\') {
145	            if (pos + 1 >= json_.size()) {
146	                break;
147	            }
148	            const char esc = json_[pos + 1];
149	            switch (esc) {
150	                case '"':  out.push_back('"');  pos += 2; break;
151	                case '\\': out.push_back('\\'); pos += 2; break;
152	                case '/':  out.push_back('/');  pos += 2; break;
153	                case 'b':  out.push_back('\b'); pos += 2; break;
154	                case 'f':  out.push_back('\f'); pos += 2; break;
155	                case 'n':  out.push_back('\n'); pos += 2; break;
156	                case 'r':  out.push_back('\r'); pos += 2; break;
157	                case 't':  out.push_back('\t'); pos += 2; break;
158	                case 'u': {
159	                    // \uXXXX：只处理 BMP 内的 ASCII 范围，其余替换为 '?'
160	                    // 看板展示的场景里，中文走 UTF-8 原样字节，不走 \u 转义
161	                    if (pos + 5 >= json_.size()) {
162	                        pos = json_.size();
163	                        break;
164	                    }
165	                    char hex[5] = {json_[pos + 2], json_[pos + 3],
166	                                   json_[pos + 4], json_[pos + 5], '\0'};
167	                    const unsigned long cp = std::strtoul(hex, nullptr, 16);
168	                    if (cp < 0x80) {
169	                        out.push_back(static_cast<char>(cp));
170	                    } else {
171	                        out.push_back('?');
172	                    }
173	                    pos += 6;
174	                    break;
175	                }
176	                default:
177	                    out.push_back(esc);
178	                    pos += 2;
179	                    break;
180	            }
181	            continue;
182	        }
183	        if (c == '"') {
184	            if (end_out) *end_out = pos + 1;
185	            return out;
186	        }
187	        out.push_back(c);
188	        ++pos;
189	    }
190	    if (end_out) *end_out = json_.size();
191	    return out;
192	}
193	
194	std::vector<std::pair<size_t, size_t>>
195	JsonReader::splitTopLevel(size_t begin, size_t end) const {
196	    std::vector<std::pair<size_t, size_t>> parts;
197	    size_t pos = begin;
198	    size_t part_start = begin;
199	    while (pos < end) {
200	        const char c = json_[pos];
201	        if (c == '"') {
202	            pos = skipString(pos);
203	            continue;
204	        }
205	        if (c == '{' || c == '[') {
206	            pos = skipContainer(pos);
207	            continue;
208	        }
209	        if (c == ',') {
210	            parts.emplace_back(part_start, pos);
211	            part_start = pos + 1;
212	        }
213	        ++pos;
214	    }
215	    if (part_start < end) {
216	        parts.emplace_back(part_start, end);
217	    }
218	    return parts;
219	}
