225	size_t JsonReader::locate(const std::string& path) const {
226	    if (path.empty()) {
227	        return std::string::npos;
228	    }
229	
230	    // 把 "a.b.c" 拆成 ["a","b","c"]
231	    std::vector<std::string> segments;
232	    {
233	        size_t start = 0;
234	        while (start <= path.size()) {
235	            const size_t dot = path.find('.', start);
236	            if (dot == std::string::npos) {
237	                segments.push_back(path.substr(start));
238	                break;
239	            }
240	            segments.push_back(path.substr(start, dot - start));
241	            start = dot + 1;
242	        }
243	    }
244	
245	    // 从根开始逐层下钻
246	    size_t pos = skipWhitespace(0);
247	    if (pos >= json_.size() || json_[pos] != '{') {
248	        return std::string::npos;
249	    }
250	    size_t container_end = skipContainer(pos);
251	    ++pos;  // 跳过 '{'
252	
253	    for (size_t seg_i = 0; seg_i < segments.size(); ++seg_i) {
254	        const std::string& key = segments[seg_i];
255	        bool found = false;
256	
257	        while (pos < container_end) {
258	            pos = skipWhitespace(pos);
259	            if (pos >= container_end || json_[pos] == '}') {
260	                break;
261	            }
262	            if (json_[pos] != '"') {
263	                // 结构异常，放弃
264	                return std::string::npos;
265	            }
266	
267	            size_t key_end = 0;
268	            const std::string cur_key = parseStringAt(pos, &key_end);
269	            pos = skipWhitespace(key_end);
270	            if (pos >= json_.size() || json_[pos] != ':') {
271	                return std::string::npos;
272	            }
273	            pos = skipWhitespace(pos + 1);
274	
275	            if (cur_key == key) {
276	                if (seg_i + 1 == segments.size()) {
277	                    return pos;  // 命中最后一层
278	                }
279	                // 还有下一层：当前值必须是对象
280	                if (pos >= json_.size() || json_[pos] != '{') {
281	                    return std::string::npos;
282	                }
283	                container_end = skipContainer(pos);
284	                ++pos;
285	                found = true;
286	                break;
287	            }
288	
289	            // 不是目标 key，跳过这个值继续找
290	            pos = skipValue(pos);
291	            pos = skipWhitespace(pos);
292	            if (pos < json_.size() && json_[pos] == ',') {
293	                ++pos;
294	            }
295	        }
296	
297	        if (!found) {
298	            return std::string::npos;
299	        }
300	    }
301	    return std::string::npos;
302	}
