/**
 * @file json_reader.cpp
 * @brief JsonReader 实现
 */

#include "json_reader.hpp"

#include <cctype>
#include <cstdlib>

namespace weaknet {
namespace dashboard {

namespace {

/**
 * @brief 判断字符是否为 JSON 空白
 *
 * 只认 RFC 8259 定义的四种：空格、水平制表、换行、回车。
 * 不用 std::isspace，因为它还认垂直制表和换页，JSON 不允许。
 */
inline bool isJsonSpace(char c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\r';
}

} // namespace

JsonReader::JsonReader(const std::string& json) : json_(json) {}

// ---------------------------------------------------------------------------
// 基础扫描
// ---------------------------------------------------------------------------

size_t JsonReader::skipWhitespace(size_t pos) const {
    while (pos < json_.size() && isJsonSpace(json_[pos])) {
        ++pos;
    }
    return pos;
}

bool JsonReader::valid() const {
    size_t begin = skipWhitespace(0);
    if (begin >= json_.size()) {
        return false;
    }
    // 只接受对象或数组开头的 JSON
    if (json_[begin] != '{' && json_[begin] != '[') {
        return false;
    }
    // 末尾必须能闭合。不校验中间内容，那是 getXxx 的事。
    size_t end = json_.size();
    while (end > begin && isJsonSpace(json_[end - 1])) {
        --end;
    }
    if (end <= begin) {
        return false;
    }
    const char last = json_[end - 1];
    return last == '}' || last == ']';
}

size_t JsonReader::skipString(size_t pos) const {
    if (pos >= json_.size() || json_[pos] != '"') {
        return pos;
    }
    ++pos;
    while (pos < json_.size()) {
        if (json_[pos] == '\\') {
            // 跳过转义字符。\uXXXX 的六字符形式也一并跳过，
            // 这里不需要真的解码，只要不误判引号即可。
            pos += 2;
            continue;
        }
        if (json_[pos] == '"') {
            return pos + 1;
        }
        ++pos;
    }
    return json_.size();
}

size_t JsonReader::skipContainer(size_t pos) const {
    if (pos >= json_.size()) {
        return pos;
    }
    const char open = json_[pos];
    if (open != '{' && open != '[') {
        return pos;
    }
    const char close = (open == '{') ? '}' : ']';

    int depth = 0;
    while (pos < json_.size()) {
        const char c = json_[pos];
        if (c == '"') {
            pos = skipString(pos);
            continue;
        }
        if (c == open) {
            ++depth;
        } else if (c == close) {
            --depth;
            if (depth == 0) {
                return pos + 1;
            }
        }
        ++pos;
    }
    return json_.size();
}

size_t JsonReader::skipValue(size_t pos) const {
    pos = skipWhitespace(pos);
    if (pos >= json_.size()) {
        return pos;
    }
    const char c = json_[pos];
    if (c == '"') {
        return skipString(pos);
    }
    if (c == '{' || c == '[') {
        return skipContainer(pos);
    }
    // 数字 / true / false / null：一直吃到分隔符
    while (pos < json_.size()) {
        const char d = json_[pos];
        if (d == ',' || d == '}' || d == ']' || isJsonSpace(d)) {
            break;
        }
        ++pos;
    }
    return pos;
}

std::string JsonReader::parseStringAt(size_t pos, size_t* end_out) const {
    std::string out;
    if (pos >= json_.size() || json_[pos] != '"') {
        if (end_out) *end_out = pos;
        return out;
    }
    ++pos;
    while (pos < json_.size()) {
        const char c = json_[pos];
        if (c == '\\') {
            if (pos + 1 >= json_.size()) {
                break;
            }
            const char esc = json_[pos + 1];
            switch (esc) {
                case '"':  out.push_back('"');  pos += 2; break;
                case '\\': out.push_back('\\'); pos += 2; break;
                case '/':  out.push_back('/');  pos += 2; break;
                case 'b':  out.push_back('\b'); pos += 2; break;
                case 'f':  out.push_back('\f'); pos += 2; break;
                case 'n':  out.push_back('\n'); pos += 2; break;
                case 'r':  out.push_back('\r'); pos += 2; break;
                case 't':  out.push_back('\t'); pos += 2; break;
                case 'u': {
                    // \uXXXX：只处理 BMP 内的 ASCII 范围，其余替换为 '?'
                    // 看板展示的场景里，中文走 UTF-8 原样字节，不走 \u 转义
                    if (pos + 5 >= json_.size()) {
                        pos = json_.size();
                        break;
                    }
                    char hex[5] = {json_[pos + 2], json_[pos + 3],
                                   json_[pos + 4], json_[pos + 5], '\0'};
                    const unsigned long cp = std::strtoul(hex, nullptr, 16);
                    if (cp < 0x80) {
                        out.push_back(static_cast<char>(cp));
                    } else {
                        out.push_back('?');
                    }
                    pos += 6;
                    break;
                }
                default:
                    out.push_back(esc);
                    pos += 2;
                    break;
            }
            continue;
        }
        if (c == '"') {
            if (end_out) *end_out = pos + 1;
            return out;
        }
        out.push_back(c);
        ++pos;
    }
    if (end_out) *end_out = json_.size();
    return out;
}

std::vector<std::pair<size_t, size_t>>
JsonReader::splitTopLevel(size_t begin, size_t end) const {
    std::vector<std::pair<size_t, size_t>> parts;
    size_t pos = begin;
    size_t part_start = begin;
    while (pos < end) {
        const char c = json_[pos];
        if (c == '"') {
            pos = skipString(pos);
            continue;
        }
        if (c == '{' || c == '[') {
            pos = skipContainer(pos);
            continue;
        }
        if (c == ',') {
            parts.emplace_back(part_start, pos);
            part_start = pos + 1;
        }
        ++pos;
    }
    if (part_start < end) {
        parts.emplace_back(part_start, end);
    }
    return parts;
}

// ---------------------------------------------------------------------------
// 路径查找
// ---------------------------------------------------------------------------

size_t JsonReader::locate(const std::string& path) const {
    if (path.empty()) {
        return std::string::npos;
    }

    // 把 "a.b.c" 拆成 ["a","b","c"]
    std::vector<std::string> segments;
    {
        size_t start = 0;
        while (start <= path.size()) {
            const size_t dot = path.find('.', start);
            if (dot == std::string::npos) {
                segments.push_back(path.substr(start));
                break;
            }
            segments.push_back(path.substr(start, dot - start));
            start = dot + 1;
        }
    }

    // 从根开始逐层下钻
    size_t pos = skipWhitespace(0);
    if (pos >= json_.size() || json_[pos] != '{') {
        return std::string::npos;
    }
    size_t container_end = skipContainer(pos);
    ++pos;  // 跳过 '{'

    for (size_t seg_i = 0; seg_i < segments.size(); ++seg_i) {
        const std::string& key = segments[seg_i];
        bool found = false;

        while (pos < container_end) {
            pos = skipWhitespace(pos);
            if (pos >= container_end || json_[pos] == '}') {
                break;
            }
            if (json_[pos] != '"') {
                // 结构异常，放弃
                return std::string::npos;
            }

            size_t key_end = 0;
            const std::string cur_key = parseStringAt(pos, &key_end);
            pos = skipWhitespace(key_end);
            if (pos >= json_.size() || json_[pos] != ':') {
                return std::string::npos;
            }
            pos = skipWhitespace(pos + 1);

            if (cur_key == key) {
                if (seg_i + 1 == segments.size()) {
                    return pos;  // 命中最后一层
                }
                // 还有下一层：当前值必须是对象
                if (pos >= json_.size() || json_[pos] != '{') {
                    return std::string::npos;
                }
                container_end = skipContainer(pos);
                ++pos;
                found = true;
                break;
            }

            // 不是目标 key，跳过这个值继续找
            pos = skipValue(pos);
            pos = skipWhitespace(pos);
            if (pos < json_.size() && json_[pos] == ',') {
                ++pos;
            }
        }

        if (!found) {
            return std::string::npos;
        }
    }
    return std::string::npos;
}

// ---------------------------------------------------------------------------
// 取值
// ---------------------------------------------------------------------------

bool JsonReader::has(const std::string& path) const {
    const size_t pos = locate(path);
    if (pos == std::string::npos) {
        return false;
    }
    // 存在但值为 null 时视为不存在
    if (json_.compare(pos, 4, "null") == 0) {
        return false;
    }
    return true;
}

std::string JsonReader::getString(const std::string& path,
                                  const std::string& fallback) const {
    const size_t pos = locate(path);
    if (pos == std::string::npos || pos >= json_.size() || json_[pos] != '"') {
        return fallback;
    }
    size_t end = 0;
    return parseStringAt(pos, &end);
}

double JsonReader::getDouble(const std::string& path, double fallback) const {
    const size_t pos = locate(path);
    if (pos == std::string::npos || pos >= json_.size()) {
        return fallback;
    }
    const char c = json_[pos];
    if (!(c == '-' || c == '+' || (c >= '0' && c <= '9'))) {
        return fallback;
    }
    const char* begin = json_.c_str() + pos;
    char* end = nullptr;
    const double value = std::strtod(begin, &end);
    if (end == begin) {
        return fallback;
    }
    return value;
}

int JsonReader::getInt(const std::string& path, int fallback) const {
    const double v = getDouble(path, static_cast<double>(fallback));
    return static_cast<int>(v);
}

bool JsonReader::getBool(const std::string& path, bool fallback) const {
    const size_t pos = locate(path);
    if (pos == std::string::npos) {
        return fallback;
    }
    if (json_.compare(pos, 4, "true") == 0) {
        return true;
    }
    if (json_.compare(pos, 5, "false") == 0) {
        return false;
    }
    return fallback;
}

std::vector<std::string>
JsonReader::getStringArray(const std::string& path) const {
    std::vector<std::string> out;
    const size_t pos = locate(path);
    if (pos == std::string::npos || pos >= json_.size() || json_[pos] != '[') {
        return out;
    }
    const size_t end = skipContainer(pos);
    size_t cursor = pos + 1;
    while (cursor < end) {
        cursor = skipWhitespace(cursor);
        if (cursor >= end || json_[cursor] == ']') {
            break;
        }
        if (json_[cursor] == '"') {
            size_t str_end = 0;
            out.push_back(parseStringAt(cursor, &str_end));
            cursor = str_end;
        } else {
            cursor = skipValue(cursor);
        }
        cursor = skipWhitespace(cursor);
        if (cursor < end && json_[cursor] == ',') {
            ++cursor;
        }
    }
    return out;
}

std::vector<std::string>
JsonReader::getObjectArray(const std::string& path) const {
    std::vector<std::string> out;
    const size_t pos = locate(path);
    if (pos == std::string::npos || pos >= json_.size() || json_[pos] != '[') {
        return out;
    }
    const size_t end = skipContainer(pos);
    size_t cursor = pos + 1;
    while (cursor < end) {
        cursor = skipWhitespace(cursor);
        if (cursor >= end || json_[cursor] == ']') {
            break;
        }
        const size_t elem_begin = cursor;
        cursor = skipValue(cursor);
        out.push_back(json_.substr(elem_begin, cursor - elem_begin));
        cursor = skipWhitespace(cursor);
        if (cursor < end && json_[cursor] == ',') {
            ++cursor;
        }
    }
    return out;
}

// ---------------------------------------------------------------------------
// 顶层数组支持
// ---------------------------------------------------------------------------

std::vector<std::string> JsonReader::getRootObjectArray() const {
    std::vector<std::string> out;
    const size_t begin = skipWhitespace(0);
    if (begin >= json_.size() || json_[begin] != '[') {
        return out;
    }
    const size_t end = skipContainer(begin);
    size_t cursor = begin + 1;
    while (cursor < end) {
        cursor = skipWhitespace(cursor);
        if (cursor >= end || json_[cursor] == ']') {
            break;
        }
        const size_t elem_begin = cursor;
        cursor = skipValue(cursor);
        out.push_back(json_.substr(elem_begin, cursor - elem_begin));
        cursor = skipWhitespace(cursor);
        if (cursor < end && json_[cursor] == ',') {
            ++cursor;
        }
    }
    return out;
}

} // namespace dashboard
} // namespace weaknet

/**
 * @file data_source.hpp
 * @brief 取数层：调用 libweaknet 的 C API 拿原始 JSON
 *
 * ## 为什么单独一层
 *
 * 数据层（`parse_xxx`）只做 JSON → POD 的纯转换，它不知道数据从哪来。
 * 取数层负责「去拿 JSON」这件事，是唯一直接调用 `weaknet_*` 的地方。
 * 解析由调用方（主线程槽函数）调 `parse_xxx()` 完成，本层不解析。
 *
 * 分开的好处：数据层可以在没有 D-Bus、没有服务端的机器上单测；
 * 取数层可以在板端用真实服务验证。
 *
 * ## 为什么必须后台线程
 *
 * `weaknet_get_*` 内部走 D-Bus 同步调用（`dbus_connection_send_with_reply_and_block`），
 * 在服务端忙或 D-Bus 卡住时会阻塞数秒。如果在 Qt 主线程调用，界面会冻结。
 *
 * ## 缓冲区策略
 *
 * C API 的签名是 `(buffer, buffer_size, error_buffer, error_size)`，
 * 返回值只表示调用成败，不告诉你需要多大缓冲区。看板的 JSON 可能较大
 * （schema v2 快照含 13 个维度 + evidence，历史 100 条），因此采用
 * **先试小缓冲区、遇到疑似截断就扩大重试**的策略。
 *
 * 注意：C API 没有明确的「缓冲区不足」错误码，截断时可能返回 true 但
 * JSON 不完整。因此这里用 `JsonReader::valid()` 判断完整性，不合法就翻倍重试。
 */

#ifndef WEAKNET_QT_DASHBOARD_DATA_SOURCE_HPP
#define WEAKNET_QT_DASHBOARD_DATA_SOURCE_HPP

#include <cstddef>
#include <string>

namespace weaknet {
namespace dashboard {

/**
 * @brief 一次取数操作的结果
 *
 * 把「成功/失败」和「失败原因」显式分开，避免调用方拿着空字符串猜。
 */
struct FetchResult {
    /// C API 是否返回成功
    bool ok = false;

    /// 失败原因（ok 为 true 时为空）
    std::string error;

    /// 原始 JSON（调试用；失败时可能为空或被截断）
    std::string json;
};

/**
 * @brief 取数层
 *
 * 所有方法都是**阻塞**的，必须在后台线程调用，不要放在 UI 线程。
 */
class DataSource {
public:
    DataSource();
    ~DataSource();

    // 禁止拷贝：内部持有 weaknet_init/cleanup 的配对状态
    DataSource(const DataSource&) = delete;
    DataSource& operator=(const DataSource&) = delete;

    /**
     * @brief 初始化 libweaknet 并建立 D-Bus 连接
     *
     * 幂等：已成功初始化后重复调用直接返回 true。
     *
     * **失败后可重试**：失败路径内部会调用 `weaknet_cleanup()` 把库的全局
     * 客户端置空，因此可以隔一段时间再次调用 `init()` 真正重连，而不是
     * 永远停留在同一个失败结果上。板端开机早期 D-Bus 尚未就绪时依赖这一点。
     *
     * @return true 成功；false 失败（可用 last_error() 取原因）
     */
    bool init();

    /**
     * @brief 释放 D-Bus 连接
     *
     * 析构时自动调用。
     */
    void cleanup();

    /// 最近一次 init() 失败的原因
    const std::string& last_error() const { return last_error_; }

    // -----------------------------------------------------------------------
    // 取数接口（全部阻塞）
    // -----------------------------------------------------------------------

    /**
     * @brief 取网络体验快照（schema v2）
     *
     * 对应 D-Bus `GetNetworkExperience`。
     * 服务端在无快照时也会返回合法的 UNKNOWN JSON，调用方用
     * `parse_experience()` + `available()` 判断，不在这里解析。
     */
    FetchResult fetch_experience_raw() const;

    /**
     * @brief 取诊断事实
     */
    FetchResult fetch_diagnosis_raw() const;

    /**
     * @brief 取历史趋势
     *
     * @param interface 网卡名；空字符串表示全部
     * @param limit     最多返回条数（服务端上限 10000，且 <=0 会被钳制为 1）
     */
    FetchResult fetch_history_raw(const std::string& interface, int limit) const;

private:
    /**
     * @brief 通用取数模板：调用 C API 并按需扩大缓冲区
     *
     * @param caller 形如 `[](char* b, size_t n, char* e, size_t en) { return weaknet_xxx(b, n, e, en); }`
     */
    template <typename Caller>
    FetchResult invoke(Caller caller) const;

    bool initialized_ = false;
    std::string last_error_;
};

} // namespace dashboard
} // namespace weaknet

#endif // WEAKNET_QT_DASHBOARD_DATA_SOURCE_HPP

