1	/**
2	 * @file main_window.cpp
3	 * @brief MainWindow 实现
4	 */
5	
6	#include "main_window.hpp"
7	
8	#include <QDateTime>
9	#include <QFont>
10	#include <QGroupBox>
11	#include <QHBoxLayout>
12	#include <QLabel>
13	#include <QPushButton>
14	#include <QSplitter>
15	#include <QStringList>
16	#include <QStatusBar>
17	#include <QTimer>
18	#include <QVBoxLayout>
19	
20	#include "data/dashboard_data.hpp"
21	#include "data_fetch_thread.hpp"
22	#include "line_chart_widget.hpp"
23	#include "theme.hpp"
24	
25	namespace weaknet {
26	namespace dashboard {
27	
28	namespace {
29	
30	/**
31	 * @brief 自动刷新间隔
32	 *
33	 * 服务端采集间隔是 10 秒（CLAUDE.md「数据采集间隔：10 秒」），
34	 * 看板刷新快于采集没有意义，只会白耗 D-Bus。这里取 10 秒对齐。
35	 */
36	constexpr int kAutoRefreshMs = 10000;
37	
38	/// 历史趋势默认取多少点
39	constexpr int kHistoryLimit = 120;
40	
41	/**
42	 * @brief 创建一行「名称 + 状态点 + 状态文本」
43	 *
44	 * @param name        维度中文名
45	 * @param state_label 输出：状态标签控件
46	 * @param dot_label   输出：状态圆点控件（跟随状态着色）
47	 * @return 该行的布局
48	 *
49	 * 布局用固定列宽而非 stretch：14 行对齐后能当表格读，
50	 * 不会因为某个维度名长一点就把状态列推歪。
51	 */
52	QWidget* make_status_row(const QString& name, QLabel** state_label,
53	                         QLabel** dot_label) {
54	    auto* row = new QWidget;
55	    auto* layout = new QHBoxLayout(row);
56	    layout->setContentsMargins(2, 2, 2, 2);
57	    layout->setSpacing(8);
58	
59	    auto* name_label = new QLabel(name);
60	    name_label->setMinimumWidth(84);
61	    name_label->setObjectName(QStringLiteral("dim_name"));
62	
63	    auto* dot = new QLabel(QStringLiteral("●"));
64	    dot->setObjectName(QStringLiteral("state_dot"));
65	    dot->setFixedWidth(14);
66	    dot->setAlignment(Qt::AlignCenter);
67	
68	    auto* state = new QLabel(QStringLiteral("--"));
69	    state->setObjectName(QStringLiteral("state_text"));
70	
71	    layout->addWidget(name_label);
72	    layout->addWidget(dot);
73	    layout->addWidget(state);
74	    layout->addStretch();
75	
76	    *state_label = state;
77	    *dot_label = dot;
78	    return row;
79	}
80	
81	} // namespace
82	
83	MainWindow::MainWindow(QWidget* parent) : QMainWindow(parent) {
84	    setWindowTitle(QStringLiteral("WeakNet 诊断看板"));
85	    resize(1024, 700);
86	    build_ui();
87	
88	    fetcher_ = new DataFetchThread(this);
89	
90	    connect(fetcher_, &DataFetchThread::experienceReady,
91	            this, &MainWindow::onExperienceReady);
92	    connect(fetcher_, &DataFetchThread::diagnosisReady,
93	            this, &MainWindow::onDiagnosisReady);
94	    connect(fetcher_, &DataFetchThread::historyReady,
95	            this, &MainWindow::onHistoryReady);
96	    connect(fetcher_, &DataFetchThread::fetchFailed,
97	            this, &MainWindow::onFetchFailed);
98	    connect(fetcher_, &DataFetchThread::refreshFinished,
99	            this, &MainWindow::onRefreshFinished);
100	
101	    // 自动刷新：QTimer 在主线程，触发时只是给后台线程打个标记，不会阻塞
102	    auto* timer = new QTimer(this);
103	    connect(timer, &QTimer::timeout, this, [this]() {
104	        if (!refresh_in_flight_) {
105	            fetcher_->requestRefresh();
106	        }
107	    });
108	    timer->start(kAutoRefreshMs);
109	}
110	
111	MainWindow::~MainWindow() = default;
112	
113	void MainWindow::start() {
114	    fetcher_->start();
115	    fetcher_->requestRefresh();
116	    refresh_in_flight_ = true;
117	}
118	
119	void MainWindow::setInterface(const QString& interface_name) {
120	    // 历史查询的网卡过滤在后台线程里读取，这里同步进去
121	    interface_ = interface_name;
122	    fetcher_->setHistoryQuery(interface_name, kHistoryLimit);
123	
124	    // 标题只用请求侧的网卡：查询全部网卡时序列里混着多个 iface，
125	    // 取数据里任意一条都会把标题写错。
126	    chart_->setTitle(interface_.isEmpty()
127	                         ? QStringLiteral("历史趋势（分数，全部网卡）")
128	                         : QStringLiteral("历史趋势（分数，%1）").arg(interface_));
129	}
130	
131	void MainWindow::build_ui() {
132	    auto* central = new QWidget;
133	    auto* root = new QVBoxLayout(central);
134	    root->setContentsMargins(12, 8, 12, 6);
135	    root->setSpacing(6);
136	
137	    // --- 顶栏 ---
138	    //
139	    // 改进前是一个扁平 QHBoxLayout：刷新按钮、网卡名、分数、状态汇总、
140	    // 档位、时间戳全部挤在同一行同一种字重里，看不出哪一项是主信息。
141	    //
142	    // 现在分三层视觉层级：
143	    //   左：操作（刷新）+ 网卡名（等宽，避免 wlan0/wlan1 混淆）
144	    //   中：分数（26pt 大字，整体状态色）+ 状态汇总色块
145	    //   右：元信息（档位、时间戳，弱化小字）
146	    auto* top = new QHBoxLayout;
147	    top->setSpacing(10);
148	
149	    refresh_button_ = new QPushButton(QStringLiteral("刷新"));
150	    refresh_button_->setCursor(Qt::PointingHandCursor);
151	    connect(refresh_button_, &QPushButton::clicked,
152	            this, &MainWindow::onRefreshClicked);
153	    top->addWidget(refresh_button_, 0, Qt::AlignVCenter);
154	
155	    iface_label_ = new QLabel(QStringLiteral("--"));
156	    iface_label_->setObjectName(QStringLiteral("iface_name"));
157	    top->addWidget(iface_label_, 0, Qt::AlignVCenter);
158	
159	    // 分数单独一列、右对齐：数字宽度会变（9.0 / 100.0），右对齐不会抖动
160	    score_label_ = new QLabel(QStringLiteral("--"));
161	    score_label_->setObjectName(QStringLiteral("score_value"));
162	    score_label_->setAlignment(Qt::AlignRight | Qt::AlignVCenter);
163	    score_label_->setMinimumWidth(96);
164	    top->addWidget(score_label_, 0, Qt::AlignVCenter);
165	
166	    // 各维度状态汇总。左侧维度列表只能逐行看，这里给出整体分布，
167	    // 一眼看出「有几个 BAD」比逐行扫快得多。
168	    summary_label_ = new QLabel;
169	    top->addWidget(summary_label_, 0, Qt::AlignVCenter);
170	
171	    top->addStretch();
172	
173	    // 右侧元信息竖排：档位在上、时间戳在下，避免横向挤占主信息宽度
174	    auto* meta = new QVBoxLayout;
175	    meta->setSpacing(0);
176	
177	    // 评估档位：不同 profile 下同一维度的判定阈值不同，
178	    // 不标出来会让「同样是 GOOD」看起来不可比。
179	    profile_label_ = new QLabel(QStringLiteral("--"));
180	    profile_label_->setObjectName(QStringLiteral("meta_info"));
181	    profile_label_->setAlignment(Qt::AlignRight);
182	    meta->addWidget(profile_label_);
183	
184	    timestamp_label_ = new QLabel(QStringLiteral("--"));
185	    timestamp_label_->setObjectName(QStringLiteral("meta_info"));
186	    timestamp_label_->setAlignment(Qt::AlignRight);
187	    meta->addWidget(timestamp_label_);
