42	    if (!weaknet_init()) {
43	        // 必须 cleanup，否则本层将永久卡死在失败状态。
44	        //
45	        // weaknet_init() 在 client.cpp:1348 的实现是：g_client 非空时直接
46	        // return g_client->isConnected()，而 connected_ 只在 initConnection()
47	        // 里赋值一次。连接失败后 g_client 仍留在全局，于是后续每次
48	        // weaknet_init() 都走 "already initialized" 分支、永远返回 false。
49	        //
50	        // weaknet_cleanup() 把 g_client 置空并 disconnect，下一次 init() 才会
51	        // 真正重建连接。副作用是它会调用 Logger::shutdown()，下次 init 再
52	        // InitGoogleLogging()——已实测 Init/Shutdown 反复循环安全。
53	        weaknet_cleanup();
54	        last_error_ = "weaknet_init() failed: cannot establish D-Bus connection";
55	        return false;
56	    }
57	    initialized_ = true;
58	    return true;
59	}
60	
61	void DataSource::cleanup() {
62	    if (initialized_) {
63	        // weaknet_cleanup() 释放内部 D-Bus 连接。
64	        // 多次调用是安全的，但这里仍用标志位确保配对。
65	        weaknet_cleanup();
66	        initialized_ = false;
67	    }
68	}
69	
70	// ---------------------------------------------------------------------------
71	// 通用取数模板
72	// ---------------------------------------------------------------------------
73	
74	template <typename Caller>
75	FetchResult DataSource::invoke(Caller caller) const {
76	    FetchResult result;
77	
78	    if (!initialized_) {
79	        result.error = "DataSource not initialized; call init() first";
80	        return result;
81	    }
82	
83	    std::vector<char> buffer(kInitialBuffer, '\0');
84	    std::vector<char> error(kErrorBufferSize, '\0');
85	
86	    while (true) {
87	        // 每轮重置，避免上一轮的残留内容干扰判断
88	        std::fill(buffer.begin(), buffer.end(), '\0');
89	        std::fill(error.begin(), error.end(), '\0');
90	
91	        const bool ok = caller(buffer.data(), buffer.size(),
92	                               error.data(), error.size());
93	
94	        // error 缓冲区非空表示服务端或库层报了明确错误
95	        const std::string error_text(error.data());
96	
97	        if (!ok) {
98	            result.error = error_text.empty()
99	                               ? "C API returned false without error message"
100	                               : error_text;
101	            result.json.assign(buffer.data());
102	            return result;
103	        }
104	
105	        // 成功时要确认内容完整：C API 不报告截断，只能自己判断。
106	        // 判定标准：非空，且 JsonReader 认为结构闭合。
107	        std::string candidate(buffer.data());
108	
109	        if (candidate.empty()) {
110	            result.error = "C API returned true but buffer is empty";
111	            return result;
112	        }
113	
114	        // 内容长度接近缓冲区上限 → 极可能被截断，扩大重试
115	        const bool near_full = candidate.size() + 1 >= buffer.size();
116	        JsonReader reader(candidate);
117	        const bool complete = reader.valid();
118	
119	        if (complete && !near_full) {
120	            result.ok = true;
121	            result.json = std::move(candidate);
122	            return result;
123	        }
124	
125	        if (buffer.size() >= kMaxBuffer) {
126	            // 已达上限仍不完整：如实报告，不假装成功
127	            result.error = "response exceeds max buffer (" +
128	                           std::to_string(kMaxBuffer) + " bytes) or is malformed";
129	            result.json = std::move(candidate);
130	            return result;
131	        }
132	
133	        buffer.resize(buffer.size() * 2);
134	    }
135	}
