139	// ---------------------------------------------------------------------------
140	
141	FetchResult DataSource::fetch_experience_raw() const {
142	    return invoke([](char* b, size_t n, char* e, size_t en) {
143	        return weaknet_get_network_experience(b, n, e, en);
144	    });
