 double y =0.0;
};

/// Y轴范围struct AxisRange {
 double lo =0.0;
 double hi =1.0;
};

///绘图区矩形（纯数值，不依赖 QRect，便于单测）
struct PlotRect {
 double left =0.0, top =0.0, width =0.0, height =0.0;
 double bottom() const { return top + height; }
 double right() const { return left + width; }
 bool usable() const { return width >1.0 && height >1.0; }
};

///计算 Y轴范围AxisRange compute_axis_range(const std::vector<double>& values, HistoryMetric metric);

///把第 i个点映射到屏幕坐标ChartPoint map_point(int index, int count, double value, const AxisRange& range, const PlotRect& plot);
