433	void MainWindow::onFetchFailed(const QString& stage, const QString& error) {
434	    // 只在状态栏提示，不弹窗：自动刷新时弹窗会烦人
435	    round_had_failure_ = true;
436	    status_bar_label_->setText(
437	        QStringLiteral("取数失败（%1）：%2").arg(stage, error));
438	}
