440	void MainWindow::onRefreshFinished() {
441	    refresh_in_flight_ = false;
442	    // 按轮复位：本轮全部成功才回到「就绪」。
443	    // 之前用「状态栏文字是否以『取数失败』开头」判断，那是跨轮持久状态——
444	    // 只要历史上失败过一次，后面每轮成功也永远停在失败文案上。
445	    if (!round_had_failure_) {
446	        status_bar_label_->setText(QStringLiteral("就绪"));
447	    }
448	    round_had_failure_ = false;
449	}
