82	void LineChartWidget::rebuild_from_series() {
83	    points_.clear();
84	    labels_.clear();
85	    const int n = static_cast<int>(series_.points.size());
86	    points_.reserve(n);
87	    labels_.reserve(n);
88	
89	    for (const HistoryPoint& p : series_.points) {
90	        PlotPoint point;
91	        point.value = p.value(metric_);
92	
93	        // 未测量：服务端 null → 哨兵值。必须显式标出来，
94	        // 否则 0 与「没测到」在图上完全一样。
95	        point.absent = is_history_metric_absent(metric_, point.value);
96	
97	        // legacy 只对 Score 有意义：它标的是「评分模型是旧的」。
98	        // RSSI / RTT 这类原始测量值不受评分模型换代影响，不该被断开。
99	        point.break_line = (metric_ == HistoryMetric::Score) && p.legacy;
100	
101	        points_.push_back(point);
102	        labels_.push_back(QString::fromStdString(p.ts));
