118	void LineChartWidget::paint(QPainter* painter, const QRect& area) const {
119	    if (!painter || area.width() <= 0 || area.height() <= 0) {
120	        return;
121	    }
122	
123	    painter->save();
124	
125	    // --- 标题 ---
126	    //
127	    // 指标名与单位由本控件拼进标题，而不是让调用方传完整字符串：
128	    // 那样 `setMetric()` 之后标题会停留在旧指标上，图和标题各说一套。
129	    // 现场终端最不能出的错就是「图上画的是 RSSI，标题写着综合分」。
130	    if (!title_.isEmpty()) {
131	        QString title = title_;
132	        title += QStringLiteral(" · ");
133	        title += QString::fromUtf8(history_metric_label(metric_));
134	        const char* unit = history_metric_unit(metric_);
135	        if (unit && unit[0] != '\0') {
136	            title += QStringLiteral(" (") + QString::fromUtf8(unit) +
137	                     QStringLiteral(")");
138	        }
139	
140	        QFont f = painter->font();
141	        f.setBold(true);
142	        painter->setFont(f);
143	        painter->setPen(theme_color(ThemeColors::kTextPrimary));
144	        painter->drawText(QRect(area.left() + kMarginLeft, area.top() + 4,
145	                                area.width() - kMarginLeft - kMarginRight,
146	                                kMarginTop - 6),
147	                          Qt::AlignLeft | Qt::AlignVCenter, title);
148	        f.setBold(false);
149	        painter->setFont(f);
150	    }
151	
152	    // --- 绘图区 ---
153	    QRect plot(area.left() + kMarginLeft,
154	               area.top() + kMarginTop,
155	               area.width() - kMarginLeft - kMarginRight,
156	               area.height() - kMarginTop - kMarginBottom);
157	
158	    if (plot.width() <= 1 || plot.height() <= 1) {
159	        painter->restore();
160	        return;
161	    }
162	
163	    // --- Y 轴范围 ---
164	    //
165	    // 只喂**有效值**给轴计算：未测量点的哨兵（-1 / -1000）若混进去，
166	    // RSSI 的轴会被拉到 -1000，真实数据全挤成一条贴顶的线。
167	    std::vector<double> valid_values;
168	    valid_values.reserve(static_cast<size_t>(points_.size()));
169	    for (const PlotPoint& p : points_) {
170	        if (!p.absent) {
171	            valid_values.push_back(p.value);
172	        }
173	    }
174	
175	    const AxisRange range = compute_axis_range(valid_values, metric_);
176	    const PlotRect plot_rect = to_plot_rect(plot);
177	
178	    // --- 网格 + Y 轴刻度 ---
179	    painter->setPen(QPen(theme_color(ThemeColors::kGrid), 1, Qt::SolidLine));
180	    QFont small = painter->font();
181	    small.setPointSizeF(std::max(7.0, small.pointSizeF() - 1.0));
182	    painter->setFont(small);
183	
184	    const int decimals = axis_label_decimals(metric_);
185	    for (int i = 0; i <= kGridLines; ++i) {
186	        const double ratio = static_cast<double>(i) / kGridLines;
187	        const int y = plot.bottom() - static_cast<int>(ratio * plot.height());
188	
189	        painter->setPen(QPen(theme_color(ThemeColors::kGrid), 1, Qt::SolidLine));
190	        painter->drawLine(plot.left(), y, plot.right(), y);
191	
192	        const double value = range.lo + ratio * (range.hi - range.lo);
193	        painter->setPen(theme_color(ThemeColors::kTextMuted));
194	        painter->drawText(QRect(area.left(), y - 8, kMarginLeft - 6, 16),
195	                          Qt::AlignRight | Qt::AlignVCenter,
196	                          QString::number(value, 'f', decimals));
197	    }
198	
199	    // --- 数据为空时的提示 ---
200	    //
201	    // 两种「空」要分开说，否则用户会去查服务端，而实际上只是这个指标
202	    // 从来没被采集过（如没有射频接口时的 RSSI）。
203	    if (points_.isEmpty() || valid_values.empty()) {
204	        painter->setPen(theme_color(ThemeColors::kTextMuted));
205	        const QString message =
206	            points_.isEmpty()
207	                ? QStringLiteral("暂无历史数据")
208	                : QStringLiteral("该指标无历史数据（%1 个采样点均未测量）")
209	                      .arg(static_cast<int>(points_.size()));
210	        painter->drawText(plot, Qt::AlignCenter, message);
211	        painter->restore();
212	        return;
213	    }
214	
215	    // --- 折线 ---
216	    const int n = points_.size();
217	
218	    // 折线色从主题取：改进前这里是一个可写成员 `line_color_`，
219	    // 但 `setLineColor()` 作为孤儿接口被删掉后再没有人改它，
220	    // 留着成员只是把「常量」伪装成「状态」。现在直接取语义色。
221	    const QColor line_color = theme_color(ThemeColors::kGood);
222	
223	    // 先把所有点换算成屏幕坐标，连线与画点共用同一份，避免两处公式漂移。
224	    // 公式本身在 chart_geometry.cpp 里，可脱离 Qt 单测。
225	    QVector<QPointF> pts;
226	    pts.reserve(n);
227	    for (int i = 0; i < n; ++i) {
228	        const ChartPoint mapped = map_point(static_cast<size_t>(i),
229	                                            static_cast<size_t>(n),
230	                                            points_[i].value, range, plot_rect);
231	        pts.push_back(QPointF(mapped.x, mapped.y));
232	    }
233	
234	    // 遇到断点就断开。两种断点：
235	    //   1. `break_line`（legacy 旧评分模型点）——分数与 v2 不同量纲，
236	    //      连成一条线会读出一段根本不存在的趋势
237	    //   2. `absent`（该指标未测量）——没有值可画，连过去就是凭空造数
238	    //
239	    // 同时记下每个连续段的起止下标：下面的面积填充要按段闭合，
240	    // 跨段填充会在断点处画出一块凭空多出来的三角。
241	    QPainterPath path;
242	    QVector<QPair<int, int>> runs;
243	    int run_begin = -1;
244	    for (int i = 0; i < n; ++i) {
245	        if (points_[i].absent || points_[i].break_line) {
246	            if (run_begin >= 0) {
247	                runs.push_back(qMakePair(run_begin, i - 1));
248	                run_begin = -1;
249	            }
250	            continue;
251	        }
252	        if (run_begin < 0) {
253	            run_begin = i;
254	            path.moveTo(pts[i]);
255	        } else {
256	            path.lineTo(pts[i]);
257	        }
258	    }
259	    if (run_begin >= 0) {
260	        runs.push_back(qMakePair(run_begin, n - 1));
261	    }
262	
263	    // --- 曲线下方的面积填充 ---
264	    //
265	    // 先填后画线，否则填充会盖住折线。透明度很低（见 kAreaFillAlpha），
266	    // 只给曲线一个「体量感」，让整体水平一眼可见，不抢折线本身。
267	    QLinearGradient fill_grad(0, plot.top(), 0, plot.bottom());
268	    QColor fill_top = line_color;
269	    fill_top.setAlpha(kAreaFillAlpha);
270	    QColor fill_bottom = line_color;
271	    fill_bottom.setAlpha(0);
272	    fill_grad.setColorAt(0.0, fill_top);
273	    fill_grad.setColorAt(1.0, fill_bottom);
274	
275	    painter->save();
276	    painter->setClipRect(plot);
277	    painter->setPen(Qt::NoPen);
278	    painter->setBrush(fill_grad);
279	    for (const QPair<int, int>& run : runs) {
280	        // 单点没有面积，闭合后会得到一条零宽竖线，跳过
281	        if (run.second <= run.first) {
282	            continue;
283	        }
284	        QPainterPath area_path;
285	        area_path.moveTo(pts[run.first].x(), plot.bottom());
286	        for (int i = run.first; i <= run.second; ++i) {
287	            area_path.lineTo(pts[i]);
288	        }
289	        area_path.lineTo(pts[run.second].x(), plot.bottom());
290	        area_path.closeSubpath();
291	        painter->drawPath(area_path);
292	    }
293	    painter->restore();
294	
295	    painter->setPen(QPen(line_color, 2, Qt::SolidLine, Qt::RoundCap, Qt::RoundJoin));
296	    painter->setBrush(Qt::NoBrush);
297	    painter->drawPath(path);
298	
299	    // 数据点少于阈值时补圆点，便于看清具体采样
300	    if (n <= kDotThreshold) {
301	        painter->setBrush(line_color);
302	        painter->setPen(Qt::NoPen);
303	        for (int i = 0; i < n; ++i) {
304	            if (!points_[i].absent && !points_[i].break_line) {
305	                painter->drawEllipse(pts[i], 2.5, 2.5);
306	            }
307	        }
308	    }
309	
310	    // legacy 点**始终**标记（灰色空心）：它们不在折线上，若再不给标记就等于
311	    // 从图上凭空消失，比画错更糟。空心也让「不是同一条趋势」一眼可辨。
312	    painter->setBrush(Qt::NoBrush);
313	    painter->setPen(QPen(theme_color(ThemeColors::kUnknown), 1.5));
314	    for (int i = 0; i < n; ++i) {
315	        if (points_[i].break_line) {
316	            painter->drawEllipse(pts[i], 2.5, 2.5);
317	        }
318	    }
319	
320	    // --- X 轴首尾时间标签 ---
321	    if (!labels_.isEmpty()) {
322	        painter->setPen(theme_color(ThemeColors::kTextMuted));
323	        painter->drawText(QRect(plot.left(), plot.bottom() + 4,
324	                                plot.width() / 2, kMarginBottom - 4),
325	                          Qt::AlignLeft | Qt::AlignTop, labels_.first());
326	        if (n > 1) {
327	            painter->drawText(QRect(plot.left() + plot.width() / 2, plot.bottom() + 4,
328	                                    plot.width() / 2, kMarginBottom - 4),
329	                              Qt::AlignRight | Qt::AlignTop, labels_.last());
330	        }
331	    }
332	
333	    painter->restore();
334	}
335	
336	} // namespace dashboard
337	} // namespace weaknet
