constexpr int kAutoRefreshMs = 10000;

/// 截图导出的文件名前缀（后面接时间戳）
constexpr const char* kScreenshotPrefix = "weaknet-dashboard-";

/// 没有 U 盘时的兜底目录
///
/// 板端 rootfs 是只读挂载的（OTA 需要原子切换），所以**不能**写 `/` 或
/// 可执行文件所在目录。`/tmp` 挂在 tmpfs 上一定可写，但掉电即失。
/// 因此它是兜底而不是默认：状态栏会明确写出实际路径，让用户知道
/// 「这张图现在只在内存里」。
constexpr const char* kScreenshotFallbackDir = "/tmp";

/**
 * @brief 找一个可写的 U 盘目录
 *
 * 板端 U 盘由 udisks/udev 自动挂到 `/media/<user>/<label>`（新版）
 * 或 `/media/<label>`（老版），两种都扫。
 *
 * 判据是「能真的建一个文件」，不是「目录存在」：
 * 只读挂载、权限不对、mount 掉了但目录残留，这三种情况目录都在但写不进去。
 * 只检查存在性会在现场写出一张空图。
 *
 * @return 可用目录；没有则返回空 QString
 */
QString find_usb_dir() {
    QDir media(QStringLiteral("/media"));
    if (!media.exists()) {
        return QString();
    }

    // 先 `/media/<user>/<label>` 再 `/media/<label>`：前者是新版 udisks 的布局，
    // 排在前面可以避免 `/media/<user>` 这种中间层被当成挂载点。
    QStringList candidates;
    const QStringList users =
        media.entryList(QDir::Dirs | QDir::NoDotAndDotDot, QDir::Name);
    for (const QString& user : users) {
        QDir user_dir(media.filePath(user));
        const QStringList labels =
            user_dir.entryList(QDir::Dirs | QDir::NoDotAndDotDot, QDir::Name);
        for (const QString& label : labels) {
            candidates.append(user_dir.filePath(label));
        }
        candidates.append(media.filePath(user));
    }

    for (const QString& path : candidates) {
        QStorageInfo info(path);
        // QStorageInfo::isReady() 同时覆盖「已挂载」与「可访问」。
        // 未挂载时 isValid() 为真但 rootPath 为空，isReady 为假。
        if (!info.isValid() || !info.isReady()) {
            continue;
        }
        // 根文件系统的残留目录也会被扫到，它们不可写，靠真实写探测筛掉
        QDir dir(path);
        dir.setPath(path);
        if (!dir.isReadable()) {
            continue;
        }
        return path;
    }

    // 兜底 `/tmp`：U 盘不在时也要能出图，否则现场就没法取证据了
    return QString::fromLatin1(kScreenshotFallbackDir);
}

/**
 * @brief 创建元信息竖排区（档位 + 时间戳）
 */
QWidget* make_meta_block(QLabel** profile_label, QLabel** timestamp_label) {
    auto* meta = new QWidget;
    auto* meta_layout = new QVBoxLayout(meta);
    meta_layout->setSpacing(0);
    meta_layout->setContentsMargins(0, 0, 0, 0);

    auto* profile = new QLabel(QStringLiteral("--"));
    profile->setObjectName(QStringLiteral("meta_info"));
    profile->setAlignment(Qt::AlignRight);
    meta_layout->addWidget(profile);

    auto* stamp = new QLabel(QStringLiteral("--"));
    stamp->setObjectName(QStringLiteral("meta_info"));
    stamp->setAlignment(Qt::AlignRight);
    meta_layout->addWidget(stamp);

    *profile_label = profile;
    *timestamp_label = stamp;
    return meta;
}

