201	    auto* central = new QWidget;
202	    auto* root = new QVBoxLayout(central);
203	    root->setContentsMargins(12, 8, 12, 6);
204	    root->setSpacing(6);
205	
206	    // --- 顶栏 ---
207	    //
208	    // 改进前是一个扁平 QHBoxLayout：刷新按钮、网卡名、分数、状态汇总、
209	    // 档位、时间戳全部挤在同一行同一种字重里，看不出哪一项是主信息。
210	    //
211	    // 现在分三层视觉层级：
