17	
18	/**
19	 * @brief 构建全局 QSS
20	 *
21	 * 结构按「容器 → 文本 → 控件」分层，与 Qt 官方的层叠顺序一致：
22	 * 同等特异性下后写的规则覆盖先写的，因此交互态（`:hover` / `:pressed`）
23	 * 必须写在基础规则之后。
24	 *
25	 * 字体统一用 sans-serif + 明确字号：eglfs 直出时没有桌面环境的字体配置，
26	 * 不指定就会落到难以预测的默认值上。
27	 */
28	QString build_stylesheet() {
29	    return QStringLiteral(R"(
30	/* ---------- 全局基底 ---------- */
31	QWidget {
32	    font-family: "Noto Sans CJK SC", "Source Han Sans SC", "WenQuanYi Micro Hei", sans-serif;
33	    font-size: 10pt;
34	    color: %1;
35	}
36	
37	QMainWindow, QDialog {
38	    background-color: %2;
39	}
40	
41	/* ---------- 分组卡片 ---------- */
42	QGroupBox {
43	    background-color: %3;
44	    border: 1px solid %4;
45	    border-radius: 6px;
46	    margin-top: 14px;
47	    padding: 6px 10px 4px 10px;
48	    font-weight: bold;
49	    color: %5;
50	}
51	
52	/* 标题压在边框上，背景要与卡片同色才能「切开」边框 */
53	QGroupBox::title {
54	    subcontrol-origin: margin;
55	    subcontrol-position: top left;
56	    left: 12px;
57	    padding: 0 6px;
58	    background-color: %3;
59	    color: %5;
60	}
61	
62	/* ---------- 文本 ---------- */
63	QLabel {
64	    background: transparent;
65	}
66	
67	/* 状态文本用等宽字体：GOOD / DEGRADED / BAD 长度不同，
68	   等宽能让左对齐的列看起来整齐 */
69	QLabel#state_text {
70	    font-family: "DejaVu Sans Mono", "Noto Sans Mono", monospace;
71	    font-size: 9pt;
72	}
73	
74	/* 整体分数：最重要的一个数字，给足视觉权重。
75	   20pt 而不是更大：主窗口最小高度是硬约束，7 寸屏常见 1024x600 / 720p，
76	   字号每涨 2pt 顶栏就多约 3px，26pt 会把最小高度顶到 728px（实测），
77	   720p 屏幕上窗口就放不下了。20pt 相对正文 10pt 仍是 2 倍，主次足够。 */
78	QLabel#score_value {
79	    font-size: 20pt;
80	    font-weight: bold;
81	}
82	
83	/* 网卡名：等宽 + 加粗，避免 wlan0 / wlan1 混淆 */
84	QLabel#iface_name {
85	    font-family: "DejaVu Sans Mono", "Noto Sans Mono", monospace;
86	    font-size: 12pt;
87	    font-weight: bold;
88	}
89	
90	/* 元信息（档位、时间戳）：弱化但不至于看不见 */
91	QLabel#meta_info {
92	    color: %6;
93	    font-size: 9pt;
94	}
95	
96	/* 底栏的经验 / 诊断文本 */
97	QLabel#detail_text {
98	    color: %6;
99	    font-size: 9pt;
100	}
101	
102	/* 底栏结论行：比明细更重要，用主文字色而非弱化色 */
103	QLabel#primary_text {
104	    color: %5;
105	    font-size: 10pt;
106	}
107	
108	/* 服务端主动标记的警告：红色是语义不是装饰，与 BAD 状态同色系 */
