171	// ---------------------------------------------------------------------------
172	
173	TEST(LineChartWidgetTest, EmptySeriesShowsNoLine) {
174	    LineChartWidget chart;
175	    const QImage img = render(chart);
176	
177	    // 没有数据时必须画提示文字，且绝不能画折线
178	    EXPECT_EQ(count_in_plot(img, /*want_line=*/true, /*want_gray=*/false), 0)
179	        << "空序列不应画出折线";
180	}
181	
182	TEST(LineChartWidgetTest, NonEmptySeriesDrawsLine) {
183	    LineChartWidget chart;
184	    chart.setSeries(make_series(10));
185	    const QImage img = render(chart);
186	
187	    // 对照组：非空序列必须真的画出折线像素
188	    EXPECT_GT(count_in_plot(img, /*want_line=*/true, /*want_gray=*/false), 0)
189	        << "非空序列必须画出折线";
190	}
191	
192	// ---------------------------------------------------------------------------
193	// legacy 断开连线（最关键的一条）
194	// ---------------------------------------------------------------------------
195	
196	TEST(LineChartWidgetTest, LegacyBreaksTheLineInTheMiddle) {
197	    // 三个点，中间那个标为 legacy（v1 旧模型）。
198	    //
199	    // 对照设计：唯一变量是中间点的 legacy 标志，其余完全相同。
200	    //   - 非 legacy：路径连续穿过中间列 → 中间列有折线像素
201	    //   - legacy：  路径在中间断开 → 中间列没有折线像素
202	    //
203	    // 三点水平等距，中间点正好在绘图区水平中心。
204	    const QRect plot = plot_rect();
205	    const int mid_x = plot.left() + plot.width() / 2;
206	    constexpr int kMidTol = 2;  // 折线宽 2px + 圆点半径 2.5px，±2 足够
207	
208	    auto count_line_near_mid_column = [&](const QImage& img) {
209	        int count = 0;
210	        for (int y = plot.top() + 1; y <= plot.bottom() - 1; ++y) {
211	            for (int dx = -kMidTol; dx <= kMidTol; ++dx) {
212	                const int x = mid_x + dx;
213	                if (x <= plot.left() || x >= plot.right()) {
214	                    continue;
215	                }
216	                if (is_line_pixel(img.pixelColor(x, y))) {
217	                    ++count;
218	                }
219	            }
220	        }
221	        return count;
222	    };
223	
224	    // --- 对照组：全部 v2，连线穿过中间列 ---
225	    LineChartWidget control;
226	    control.setSeries(make_series(3, /*all_legacy=*/false));
227	    const QImage control_img = render(control);
228	
229	    // --- 实验组：中间点 legacy，连线断开 ---
230	    HistorySeries mixed = make_series(3, /*all_legacy=*/false);
231	    mixed.points[1].legacy = true;
232	
233	    LineChartWidget subject;
234	    subject.setSeries(mixed);
235	    const QImage subject_img = render(subject);
236	
237	    const int control_mid = count_line_near_mid_column(control_img);
238	    const int subject_mid = count_line_near_mid_column(subject_img);
239	
240	    EXPECT_GT(control_mid, 0)
241	        << "对照组：三个 v2 点应连成一条穿过中间列的线";
242	    EXPECT_EQ(subject_mid, 0)
243	        << "中间点标为 legacy 后，连线必须在该处断开";
244	
245	    // 两侧的线还在：证明只在 legacy 处断开，而不是整条线都没画
246	    EXPECT_GT(count_in_plot(subject_img, /*want_line=*/true, /*want_gray=*/false), 0)
247	        << "legacy 只断开它自己那一段，其余线段必须仍然存在";
248	}
249	
250	TEST(LineChartWidgetTest, LegacyPointsAreStillMarked) {
251	    // legacy 点不在折线上。若再不给标记就等于从图上凭空消失，
252	    // 比画错更糟——用户会以为那几个采样根本不存在。
253	    LineChartWidget chart;
254	    chart.setSeries(make_series(3, /*all_legacy=*/true));
255	    const QImage img = render(chart);
256	
257	    // 全 legacy 时不应有任何折线
258	    EXPECT_EQ(count_in_plot(img, /*want_line=*/true, /*want_gray=*/false), 0)
259	        << "全 legacy 序列不应画出折线";
260	
261	    // 但必须有灰色标记
262	    EXPECT_GT(count_in_plot(img, /*want_line=*/false, /*want_gray=*/true), 0)
263	        << "legacy 点必须留下灰色空心标记，不能静默消失";
264	}
265	
266	// ---------------------------------------------------------------------------
267	// 几何与坐标变换
268	// ---------------------------------------------------------------------------
269	
270	TEST(LineChartWidgetTest, SinglePointRendersWithoutDivisionByZero) {
271	    // n == 1 时 x_ratio 被特意设为 0.5，避免除零。
272	    // 这类边界不值得为它崩一次界面。
273	    LineChartWidget chart;
274	    chart.setSeries(make_series(1));
275	    const QImage img = render(chart);
276	
277	    EXPECT_GT(count_in_plot(img, /*want_line=*/true, /*want_gray=*/false), 0)
278	        << "单点也必须画出来（画成圆点，不画线）";
279	}
280	
281	TEST(LineChartWidgetTest, FlatSeriesDoesNotCollapseToEdge) {
282	    // 全等值序列：hi == lo，y_ratio 会退化成 0.5。
283	    // 若没有 span 兜底，取值会落到绘图区顶部或底部，看起来像"贴顶"。
284	    HistorySeries flat;
285	    for (int i = 0; i < 5; ++i) {
286	        HistoryPoint p;
287	        p.ts = "2026-11-06 12:00:0" + std::to_string(i);
288	        p.score = 55.0;
289	        flat.points.push_back(std::move(p));
290	    }
291	
292	    LineChartWidget chart;
293	    chart.setSeries(flat);
294	    const QImage img = render(chart);
295	
296	    // 折线应出现在绘图区的垂直中部，而不是最上一行或最下一行
297	    const QRect plot = plot_rect();
298	    const int mid_y = plot.top() + plot.height() / 2;
299	    constexpr int kTol = 6;
300	
301	    int near_mid = 0;
302	    for (int y = mid_y - kTol; y <= mid_y + kTol; ++y) {
303	        for (int x = plot.left() + 1; x <= plot.right() - 1; ++x) {
304	            if (is_line_pixel(img.pixelColor(x, y))) {
305	                ++near_mid;
306	            }
307	        }
308	    }
309	    EXPECT_GT(near_mid, 0) << "全等值序列应画在垂直中部";
310	}
311	
312	TEST(LineChartWidgetTest, LegacyVectorStaysInSyncWithScores) {
313	    // legacy_ 与 scores_ 必须等长：paint() 里用 legacy_.at(i) 索引，
314	    // 长度不一致会越界。连续换两次数据是这个不变量的最容易破的时刻。
315	    LineChartWidget chart;
316	    chart.setSeries(make_series(10));
317	    chart.setSeries(make_series(3, /*all_legacy=*/true));
318	    const QImage img = render(chart);
319	
320	    // 换过数据后不应崩，且只能看到 3 个 legacy 点、没有折线
321	    EXPECT_EQ(count_in_plot(img, /*want_line=*/true, /*want_gray=*/false), 0);
322	    EXPECT_GT(count_in_plot(img, /*want_line=*/false, /*want_gray=*/true), 0);
323	}
324	
325	TEST(LineChartWidgetTest, DegenerateAreaIsIgnored) {
326	    // paint() 对空矩形必须安全返回，不能崩。
327	    // paintEvent 在窗口最小化等情况下可能给出极小的 rect。
328	    LineChartWidget chart;
329	    chart.setSeries(make_series(5));
330	
331	    QImage img(10, 10, QImage::Format_RGB32);
332	    img.fill(Qt::white);
333	    QPainter painter(&img);
334	    chart.paint(&painter, QRect(0, 0, 0, 0));
335	    chart.paint(&painter, QRect(0, 0, 5, 5));   // 比边距还小
336	    painter.end();
337	
338	    SUCCEED();  // 没崩就算通过
339	}
340	
341	} // namespace
