191	    // 状态色要能压在白卡片上读出来。WCAG AA 正文要求 4.5:1，
192	    // 这里按相对亮度公式独立复算，不依赖外部工具。
193	    auto relative_luminance = [](const QColor& c) {
194	        auto channel = [](double v) {
195	            const double s = v / 255.0;
196	            return s <= 0.03928 ? s / 12.92 : std::pow((s + 0.055) / 1.055, 2.4);
197	        };
198	        return 0.2126 * channel(c.red()) + 0.7152 * channel(c.green()) +
199	               0.0722 * channel(c.blue());
200	    };
