 * |------|------|---------|
 * | `eglfs` | DRM/KMS + EGL | ✅ **推荐**（直连 HDMI） |
 * | `linuxfb` | `/dev/fb*` | ❌ 板端无 fbdev |
 * | `xcb` | Xorg | ❌ 无图形栈运行 |
 * | `offscreen` | 无 | ✅ 仅用于测试，不显示 |
 *
 * 因此默认走 `eglfs`，但允许用 `-platform` 参数或 `QT_QPA_PLATFORM` 环境变量
 * 覆盖（调试时用 `offscreen`）。两个例外由 `apply_default_platform()` 处理：
 * 显式指定时完全不干预；带 `--screenshot` 时自动改用 `offscreen`，因为该选项
 * 的用途就是「无显示器验证」，此时 eglfs 会在启动阶段因拿不到 DRM 而失败。
 *
 * ## 权限
 *
 * `eglfs` 需要打开 `/dev/dri/card0`，通常要求 root 或 `video` 组成员。
 * 若启动报 `Permission denied`，检查：
 *
 * ```bash
 * ls -l /dev/dri/card0
 * groups
 * sudo usermod -aG video $USER
 * ```
 *
 * ## 无显示器验证：--screenshot
 *
 * 没有 HDMI 显示器时，用 `offscreen` 平台插件跑起来，等首次取数完成后
 * 把窗口 `grab()` 成 PNG。这样能在接显示器之前就验证「数据真的画上去了」：
 *
 * ```bash
 * QT_QPA_PLATFORM=offscreen ./weaknet_dashboard --screenshot /tmp/dash.png
 * ```
 *
 * 截图后进程自动退出，适合脚本与 CI。
 */

#include <QApplication>
#include <QByteArray>
#include <QCommandLineParser>
#include <QPixmap>
#include <QTimer>

#include <cstdlib>
#include <cstring>

#include "ui/main_window.hpp"
#include "ui/theme.hpp"

/**
 * @brief argv 里是否出现了 `--screenshot`（或 `--screenshot=...`）
 *
 * 为什么手工扫 argv 而不是用 QCommandLineParser：
 * 平台插件在 `QApplication` **构造时**就要确定，而 parser 是构造之后
 * 才能处理的。要在那之前决定默认平台插件，只能自己看 argv。
 *
 * 只认长选项：`--screenshot` 没有短形式，这里也不该为它发明一个。
 */
static bool has_screenshot_option(int argc, char* argv[]) {
    static const char kOpt[] = "--screenshot";
    constexpr size_t kOptLen = sizeof(kOpt) - 1;
    for (int i = 1; i < argc; ++i) {
        const char* arg = argv[i];
        if (!arg) {
            continue;
        }
        if (std::strncmp(arg, kOpt, kOptLen) == 0 &&
            (arg[kOptLen] == '\0' || arg[kOptLen] == '=')) {
            return true;
        }
    }
    return false;
}

/**
 * @brief 未显式指定平台插件时，决定默认值
 *
 * 头注释推荐了 `eglfs`，但在此之前代码里没有设置任何默认值：完全依赖
 * `QT_QPA_PLATFORM` 环境变量，未设置时由 Qt 在可用插件里自行挑选，板端
 * 挑到哪个不确定。这里把推荐落到实处。
 *
 * 优先级（已实测确认，见下）：
 *
 * 1. `QT_QPA_PLATFORM` 环境变量已设置 → 不动
 * 2. 显式 `-platform <x>` → 由 Qt 自己处理，会压过这里 qputenv 的值
 * 3. `--screenshot` → 用 `offscreen`。这个选项的用途就是「无显示器验证」，
 *    此时默认 eglfs 会在 QApplication 构造时因拿不到 DRM/EGL 直接失败，
 *    根本走不到截图逻辑。
 * 4. 其余 → `eglfs`
 *
 * 实测依据（x86 无 DRM 环境）：
 *   - 不设环境变量：报 "Could not initialize egl display"（默认 eglfs 生效）
 *   - `-platform offscreen`：platformName() == "offscreen"（命令行压过默认）
 *   - 环境变量 offscreen：platformName() == "offscreen"（不被覆盖）
 */
static void apply_default_platform(int argc, char* argv[]) {
    if (!qEnvironmentVariableIsEmpty("QT_QPA_PLATFORM")) {
        return;  // 调用方已显式指定（命令行 -platform 或环境变量）
    }
    qputenv("QT_QPA_PLATFORM",
            has_screenshot_option(argc, argv) ? QByteArrayLiteral("offscreen")
                                             : QByteArrayLiteral("eglfs"));
}

int main(int argc, char* argv[]) {
    apply_default_platform(argc, argv);
    QApplication app(argc, argv);

    QApplication::setApplicationName(QStringLiteral("weaknet-dashboard"));
    QApplication::setApplicationVersion(QStringLiteral("0.1.0"));
    QApplication::setOrganizationName(QStringLiteral("WeakNet"));

    // 全局外观必须在窗口构造前就位：QSS 是「样式已设置时立刻重算」，
    // 晚设置会让窗口先以原生样式布局一次，再跳变成主题样式。
    qInfo("theme: %s", qPrintable(weaknet::dashboard::apply_theme()));

    QCommandLineParser parser;
    parser.setApplicationDescription(
        QStringLiteral("WeakNet 本地诊断看板（实验性）"));
    parser.addHelpOption();
    parser.addVersionOption();

    QCommandLineOption iface_option(
        QStringList() << QStringLiteral("i") << QStringLiteral("interface"),
        QStringLiteral("指定网卡；不传则查询全部网卡"),
        QStringLiteral("name"));
    parser.addOption(iface_option);

    QCommandLineOption shot_option(
        QStringLiteral("screenshot"),
        QStringLiteral("取数完成后把窗口存为 PNG 并退出（无显示器验证用）"),
        QStringLiteral("path"));
    parser.addOption(shot_option);

    QCommandLineOption shot_delay_option(
        QStringLiteral("screenshot-delay"),
        QStringLiteral("截图前等待的毫秒数，留给首轮取数（默认 3000）"),
        QStringLiteral("ms"),
        QStringLiteral("3000"));
    parser.addOption(shot_delay_option);

    parser.process(app);

    weaknet::dashboard::MainWindow window;
    // 无论是否传 -i 都调用：setInterface("") 会把标题写成「全部网卡」，
    // 同时把 history_limit_ 设成与 -i 时同一个值。之前只在 isSet 时调用，
    // 导致不传 -i 时标题停在 build_ui 的默认文案、limit 也停在类默认值，
    // 与「查询全部网卡」的实际行为对不上。
    window.setInterface(parser.isSet(iface_option)
                            ? parser.value(iface_option)
                            : QString());
    window.show();
    window.start();

    if (parser.isSet(shot_option)) {
        const QString path = parser.value(shot_option);
        const int delay_ms = parser.value(shot_delay_option).toInt();
        // 等待后台线程完成首轮取数，再抓窗口。
        // 用 singleShot 而不是 sleep：sleep 会阻塞事件循环，信号送不回主线程，
        // 界面就永远是未刷新状态。
        QTimer::singleShot(delay_ms > 0 ? delay_ms : 0, &window, [&window, path]() {
            const QPixmap shot = window.grab();
            if (shot.isNull()) {
                qWarning("screenshot: grab() returned null");
                QCoreApplication::exit(2);
                return;
            }
            if (!shot.save(path, "PNG")) {
                qWarning("screenshot: cannot save to %s", qPrintable(path));
                QCoreApplication::exit(3);
                return;
            }
            qInfo("screenshot: %dx%d saved to %s",
                  shot.width(), shot.height(), qPrintable(path));
            QCoreApplication::quit();
        });
    }

    return app.exec();
}

/**
 * @file main_window.hpp
 * @brief 看板主窗口
 *
 * ## 布局
 *
 * ```
 * ┌─────────────────────────────────────────────┐
 * │ [刷新] wlan0  GOOD 85.2  2026-11-05 20:31   │  ← 顶栏
 * ├──────────────┬──────────────────────────────┤
 * │ 网络健康      │                              │
 * │  IP 可达  ●  │      历史趋势折线图            │
 * │  响应性   ●  │                              │
 * │  可靠性   ●  │                              │
 * │  RF 健康  ○  │                              │
 * ├──────────────┤                              │
 * │ 服务健康      │                              │
 * │  DNS      ●  │                              │
 * │  TCP 连接 ●  │                              │
 * │  ...         │                              │
 * ├──────────────┴──────────────────────────────┤
 * │ 诊断：故障域 DNS · 首要问题 dns_timeout      │  ← 底栏
 * └─────────────────────────────────────────────┘
 * ```
 *
 * ## 状态色的取值依据
 *
 * `server/include/assurance/health_state.hpp:15-23`：
 * GOOD / DEGRADED / BAD / UNKNOWN。
 */

#ifndef WEAKNET_QT_DASHBOARD_MAIN_WINDOW_HPP
#define WEAKNET_QT_DASHBOARD_MAIN_WINDOW_HPP

#include <QByteArray>
#include <QMainWindow>
#include <QString>

#include "data/dashboard_data.hpp"

class QComboBox;
class QHBoxLayout;
class QLabel;
class QPushButton;

namespace weaknet {
namespace dashboard {

class DataFetchThread;
class LineChartWidget;

/**
 * @brief 看板主窗口
 */
class MainWindow : public QMainWindow {
    Q_OBJECT

public:
    explicit MainWindow(QWidget* parent = nullptr);
    ~MainWindow() override;

    /**
     * @brief 启动后台取数与自动刷新
     *
     * 不从构造函数调用：构造时窗口还没显示，立刻取数会拖慢启动。
     */
    void start();

    /**
     * @brief 指定历史趋势查询的网卡，并据此设置图表标题
     *
     * 空字符串表示不限制（服务端按全部网卡返回），标题会写成「全部网卡」。
     *
     * 必须在 `start()` 之前调用。`main.cpp` **无条件调用**（不传 `-i` 时传空串）：
     * 它同时负责设置 `history_limit_` 和标题，跳过调用会让标题与实际查询范围对不上。
     */
    void setInterface(const QString& interface_name);

    // -----------------------------------------------------------------------
    // 展示态的可观测面
    //
    // 这两个是**只读访问器**，给测试与将来可能的持久化用。
    // 不提供 setter：所有写入路径都必须走 onMetricSelected() /
    // onWindowSelected()，那两个函数里带着「切换不能重置另一维」的约束。
    // 一旦开了 setter，这个约束就没有守卫了。
    // -----------------------------------------------------------------------

    /// 当前绘制的指标
    HistoryMetric current_metric() const { return current_metric_; }

    /// 当前查询的时间窗
    HistoryWindow current_window() const { return current_window_; }

private slots:
    void onExperienceReady(const QByteArray& json);
    void onDiagnosisReady(const QByteArray& json);
    void onHistoryReady(const QByteArray& json);
    void onFetchFailed(const QString& stage, const QString& error);
    void onRefreshFinished();
    void onRefreshClicked();

    /// 指标选择器变更（白名单第 1 项）
    ///
    /// **只换视图，不重置时间窗**：用户先选「24 小时」再切到 RSSI，
    /// 期望看的仍然是 24 小时的 RSSI。
    void onMetricSelected(int index);

    /// 时间窗按钮点击（白名单第 2 项）
    ///
    /// **只换取数范围，不重置指标**，理由同上。
    void onWindowSelected(int window_id);

    /// 导出当前画面为 PNG（白名单第 3 项）
    void onExportClicked();

private:
    void build_ui();
    /// 顶栏右侧的展示态控制区（指标选择器 + 时间窗按钮 + 导出）
    void build_view_controls(QHBoxLayout* top);
    void apply_experience(const ExperienceSnapshot& snap);
    void apply_diagnosis(const DiagnosisSnapshot& snap);
    void update_status_label(const SleItem& item, QLabel* state_label,
                             QLabel* dot_label);
    static QString state_color(const QString& state);

    /// 重算图标题（网卡 + 指标 + 窗口），并把它交给 LineChartWidget
    void refresh_chart_title();

    /// 把当前画面存成 PNG，返回实际写入路径（失败为空）
    QString export_screenshot();

    DataFetchThread* fetcher_ = nullptr;
    LineChartWidget* chart_ = nullptr;

    /// 历史查询使用的网卡（空表示全部）。
    ///
    /// 这是**请求侧**的事实，不能从 `HistorySeries` 推断：
    /// 查询全部网卡时，任意一条记录的 iface 都不代表整个序列。
    /// 折线图标题直接用它，避免出现「标题写着 wlan0，实际混了 eth0」。
    QString interface_;

    // 顶栏
    QPushButton* refresh_button_ = nullptr;
    QLabel* iface_label_ = nullptr;
    QLabel* score_label_ = nullptr;
    QLabel* timestamp_label_ = nullptr;

    // -----------------------------------------------------------------------
    // 展示态控制（现场交互终端白名单的落地点）
    //
    // 产品定位 v1.2 允许现场改的只有「展示态」：看哪个指标、看多长时间、
    // 把当前画面导出。这三个控件就是那三项，**一个不多**。
    //
    // 绝对不在这里加的东西（违反白名单会直接越过权责契约）：
    //   - 触发 pending_actions / 执行动作
    //   - 改阈值、改配置
    //   - 重启服务、重连
    //   - 任何“就地算一个结论”的按钮
    //
    // 新增交互点前先读 `docs/产品定位-工业无线诊断网关.md` 第三节之二。
    // -----------------------------------------------------------------------

    /// 趋势指标选择器（白名单第 1 项）
    QComboBox* metric_combo_ = nullptr;

    /// 时间窗按钮（白名单第 2 项）：1h / 6h / 24h，互斥
    QPushButton* window_1h_button_ = nullptr;
    QPushButton* window_6h_button_ = nullptr;
    QPushButton* window_24h_button_ = nullptr;

    /// 截图导出（白名单第 3 项）
    QPushButton* export_button_ = nullptr;

    /// 当前展示的指标与时间窗。切换时二者互不干扰：
    /// 换窗口不能把指标重置，换指标也不能把窗口重置。
    HistoryMetric current_metric_ = HistoryMetric::Score;
    HistoryWindow current_window_ = HistoryWindow::Last1h;

    /// 各维度状态汇总「● 3 ● 2 ● 1 ○ 7」（count_by_state 的消费者）
    QLabel* summary_label_ = nullptr;
    /// 评估档位与覆盖度（assessment_profile 的消费者）
    QLabel* profile_label_ = nullptr;

    // 维度状态标签（顺序与 dashboard_data.hpp 中字段一致）
    QLabel* ip_reachability_label_ = nullptr;
    QLabel* responsiveness_label_ = nullptr;
    QLabel* reliability_label_ = nullptr;
    QLabel* rf_health_label_ = nullptr;

    QLabel* dns_label_ = nullptr;
    QLabel* tcp_connect_label_ = nullptr;
    QLabel* tcp_rtt_label_ = nullptr;
    QLabel* http_access_label_ = nullptr;
    QLabel* captive_portal_label_ = nullptr;
    QLabel* active_dns_label_ = nullptr;
    QLabel* active_tcp_label_ = nullptr;
    QLabel* active_https_label_ = nullptr;
    QLabel* active_portal_label_ = nullptr;

    // 每个维度左侧的状态圆点。
    //
    // 圆点与状态文本分别持有指针：`update_status_label()` 要在一次调用里
    // 同时给两者上色。改进前圆点由 `make_status_row()` 创建后就没再被引用，
    // 永远保持默认前景色，14 行扫下来看不出哪几项异常。
    QLabel* ip_reachability_dot_ = nullptr;
    QLabel* responsiveness_dot_ = nullptr;
    QLabel* reliability_dot_ = nullptr;
    QLabel* rf_health_dot_ = nullptr;

    QLabel* dns_dot_ = nullptr;
    QLabel* tcp_connect_dot_ = nullptr;
    QLabel* tcp_rtt_dot_ = nullptr;
    QLabel* http_access_dot_ = nullptr;
    QLabel* captive_portal_dot_ = nullptr;
    QLabel* active_dns_dot_ = nullptr;
    QLabel* active_tcp_dot_ = nullptr;
    QLabel* active_https_dot_ = nullptr;
    QLabel* active_portal_dot_ = nullptr;

    // 底栏
    //
    // experience 与 diagnosis 是**两个独立的异步数据源**，返回时序不定
    // （DataFetchThread 先发 experienceReady 再发 diagnosisReady，但二者
    // 都是队列连接，实际到达顺序不保证）。因此它们各自拥有独立控件：
    // 共用一个 QLabel 会让后到者覆盖先到者的内容。
    /// 体验快照的结论行：等待评估原因 / 首要问题（experience 独占）
    QLabel* experience_label_ = nullptr;
    /// 体验快照的警告（experience 独占，无警告时隐藏）
    QLabel* experience_detail_label_ = nullptr;
    /// 诊断结论行：故障域 + 置信度 + 动作数（diagnosis 独占）
    QLabel* diagnosis_label_ = nullptr;
    /// 诊断的人读摘要（diagnosis 独占，default_summary_template 的消费者）
    QLabel* summary_template_label_ = nullptr;
    /// 次要问题 / 已排除原因 / 证据（diagnosis 独占，可折叠）
    QLabel* diagnosis_extra_label_ = nullptr;
    QLabel* status_bar_label_ = nullptr;

    /// 本轮刷新是否出现过失败。
    ///
    /// 不能用「状态栏文字是否以『取数失败』开头」判断：那是跨轮持久的状态，
    /// 一旦出现过失败，之后即使每轮都成功也永远不会复位回「就绪」。
    /// 这里按轮记录，onRefreshFinished 时消费并清空。
    bool round_had_failure_ = false;

    bool refresh_in_flight_ = false;
};

} // namespace dashboard
} // namespace weaknet

