import zlib, struct, sys
from collections import Counter

def load_png(path):
    data = open(path,'rb').read()
    pos = 8; idat = b''; w=h=bd=ct=0
    while pos < len(data):
        ln = struct.unpack('>I', data[pos:pos+4])[0]
        typ = data[pos+4:pos+8]; chunk = data[pos+8:pos+8+ln]
        if typ == b'IHDR': w,h,bd,ct,_,_,_ = struct.unpack('>IIBBBBB', chunk)
        elif typ == b'IDAT': idat += chunk
        elif typ == b'IEND': break
        pos += 12 + ln
    nch = {0:1,2:3,3:1,4:2,6:4}[ct]
    raw = zlib.decompress(idat); stride = w*nch
    out = bytearray(h*stride); prev = bytearray(stride); p = 0
    for y in range(h):
        f = raw[p]; p += 1
        line = bytearray(raw[p:p+stride]); p += stride
        if f == 1:
            for i in range(nch, stride): line[i] = (line[i]+line[i-nch]) & 0xFF
        elif f == 2:
            for i in range(stride): line[i] = (line[i]+prev[i]) & 0xFF
        elif f == 3:
            for i in range(stride):
                a = line[i-nch] if i>=nch else 0
                line[i] = (line[i]+((a+prev[i])>>1)) & 0xFF
        elif f == 4:
            for i in range(stride):
                a = line[i-nch] if i>=nch else 0; b = prev[i]
                c = prev[i-nch] if i>=nch else 0
                pp = a+b-c; pa,pb,pc = abs(pp-a),abs(pp-b),abs(pp-c)
                pr = a if (pa<=pb and pa<=pc) else (b if pb<=pc else c)
                line[i] = (line[i]+pr) & 0xFF
        out[y*stride:(y+1)*stride] = line; prev = line
    return w,h,nch,bytes(out)

path = sys.argv[1]
w,h,nch,px = load_png(path)
def rgb(x,y):
    i=(y*w+x)*nch; return px[i],px[i+1],px[i+2]

print(f"== {path}  {w}x{h} nch={nch} ==")
# exact color histogram
c = Counter()
for y in range(0,h,1):
    for x in range(0,w,1):
        c[rgb(x,y)] += 1
total = w*h
print("\n-- top 8 exact colors --")
for col,n in c.most_common(8):
    print(f"  {col}  {n:7d}  {n*100.0/total:5.2f}%")

# theme checks
def has(col, tol=2):
    return c.get(col,0)
checks = [
    ("页面底色 #F5F6F8", (0xF5,0xF6,0xF8)),
    ("卡片白 #FFFFFF",   (0xFF,0xFF,0xFF)),
    ("分隔线 #E0E3E8",   (0xE0,0xE3,0xE8)),

