std::string DatabaseManager::queryHistory(const std::string& interface,
                                           const std::string& start,
                                           const std::string& end,
                                                 int limit) {
    if (!db_) return "[]";
    std::lock_guard<std::mutex> lock(mutex_);

    // 使用参数绑定防止 SQL 注入
    std::string sql = "SELECT ts, iface, rtt_ms, jitter_ms, rssi_dbm, rssi_source, rssi_estimated, rssi_status, rtt_status, jitter_status, tcp_loss_status, traffic_status, tcp_loss, quality, link_quality, overall_quality, overall_score, score, traffic_bps, traffic_pps, flows, snapshot_ts, generation, data_version, rtt_sample_ts, rssi_sample_ts, jitter_sample_ts, tcp_loss_sample_ts, traffic_sample_ts, score_model, assessment_profile, tcp_retrans_loss_pct, tcp_conn_active, tcp_conn_accepts "
                      "FROM network_history WHERE 1=1";

    std::vector<std::string> conditions;
    if (!interface.empty()) {
        sql += " AND iface=?";
        conditions.push_back(interface);
    }
    if (!start.empty()) {
        sql += " AND ts>=?";
        conditions.push_back(start);
    }
    if (!end.empty()) {
        sql += " AND ts<=?";
        conditions.push_back(end);
    }

    sql += " ORDER BY ts DESC LIMIT ?";

    sqlite3_stmt* stmt = nullptr;
    int rc = sqlite3_prepare_v2(db_, sql.c_str(), -1, &stmt, nullptr);
    if (rc != SQLITE_OK) {
        LOG_ERROR(LogModule::SYSTEM, "DatabaseManager::queryHistory prepare failed: " << sqlite3_errmsg(db_));
        return "[]";
    }

    // 绑定参数
    int paramIndex = 1;
    for (const auto& cond : conditions) {
        sqlite3_bind_text(stmt, paramIndex++, cond.c_str(), -1, SQLITE_TRANSIENT);
    }
    sqlite3_bind_int(stmt, paramIndex, limit);

    HistoryCallbackCtx ctx;
    rc = sqlite3_step(stmt);
    while (rc == SQLITE_ROW) {
